import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/software-exam/ispm/project-integration-management/comprehensive-exercises/","title":"10 综合练习 | 软考","lang":"zh-CN","frontmatter":{"title":"10 综合练习","createTime":"2026-11-22T21:20:00.000Z","permalink":"/software-exam/ispm/project-integration-management/comprehensive-exercises/","outline":false,"aside":false},"readingTime":{"minutes":113.87,"words":34160},"git":{"createdTime":1795354081000},"filePathRelative":"software-exam/ispm/project-integration-management/10.comprehensive-exercises.md","headers":[],"bulletin":false}`),a={name:`10.comprehensive-exercises.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="exam-note"><p><a id="q1" class="quiz-anchor"></a></p><p><strong>1.</strong> 关于项目整合管理目标的描述，正确的是（ ）。①平衡竞争性需求②研究各种备选方法③整合过程以实现项目目标“④管理各个项目管理知识领域之间的依赖关系&quot;⑤提高资源的使用效率</p><ul><li>A．①②④</li><li>B．①B5</li><li>C．②③④</li><li>D．①②⑤</li></ul><details class="quiz" data-q="1" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目整合管理的目标包括：①资源分配；②平衡意争性需求；③研究各种备选方法；④裁剪过程以实现项目目标；⑤管理各个项目管理知识领域之间的依赖关系（P237）　<span class="quiz-src">自编</span></p></details><p><a id="q2" class="quiz-anchor"></a></p><p><strong>2.</strong> 项目整合管理由（ ）负责，整合所有其他知识领域成果，掌握项目总体情况。</p><ul><li>A．项目团队</li><li>B．项目经理</li><li>C．项目启动者</li><li>D．项目发起人</li></ul><details class="quiz" data-q="2" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目整合管理由项目经理负责。项目经理负责整合所有其他知识领域的成果，并掌握项目总体情况（P237）　<span class="quiz-src">教材第 8 章章节习题</span></p></details><p><a id="q3" class="quiz-anchor"></a></p><p><strong>3.</strong> 关于整合管理，下面（ ）是不正确的。</p><ul><li>A．项目整合管理由项目经理负责，项目经理负责整合所有其他知识领域的成果，并掌握项目总体情况</li><li>B．项目整合管理的责任可以被授权或转移，项目经理不一定对整个项目承担最终责任</li><li>C．组织层面上，项目经理扮演重要角色，与项目发起人携手合作，了解战略目标并确保项目目标和成果与项目组合、项目集以及业务领域保持一致</li><li>D．在项目层面上，项目经理负责指导团队关注真正重要的事务并协同工作。为此，项目经理需要整合过程、知识和人员</li></ul><details class="quiz" data-q="3" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：237。项目整合管理的责任不能被授权或转移，项目经理必须对整个项目承担最终责任　<span class="quiz-src">自编</span></p></details><p><a id="q4" class="quiz-anchor"></a></p><p><strong>4.</strong> 项目整合管理的目标不包括（ ）。</p><ul><li>A．资源分配</li><li>B．平衡竞争性需求</li><li>C．研究各种备选方法</li><li>D．管理各种制约因素</li></ul><details class="quiz" data-q="4" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目整合管理的目标包括：①资源分配；②平衡竞争性需求；③研究各种备选方法；④裁剪过程以实现项目目标；⑤管理各个项目管理知识领域之间的依赖关系（P237）　<span class="quiz-src">自编</span></p></details><p><a id="q5" class="quiz-anchor"></a></p><p><strong>5.</strong> 项目整合管理的目标不包括（ ）。</p><ul><li>A．管理各个项目管理知识领域之间的依赖关系</li><li>B．裁剪过程以实现项目目标</li><li>C．研究各种备选方法</li><li>D．确保项目资源的高效利用</li></ul><details class="quiz" data-q="5" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目整合管理的目标包括：①资源分配；②平衡竞争性需求；③研究各种备选方法；④裁剪过程以实现项目目标；⑤管理各个项目管理知识领域之间的依赖关系（P237）　<span class="quiz-src">自编</span></p></details><p><a id="q6" class="quiz-anchor"></a></p><p><strong>6.</strong> 项目整合管理由（ ）负责，其责任不能被授权或转移，（ ）是项目经理的一项关键技能，同时项目整合管理需要管理各个项目管理知识领域之间的（ ）。</p><ul><li>A．项目团队、整合、协作关系</li><li>B．项目经理、整合、依赖关系</li><li>C．项目负责人、沟通、协作关系</li><li>D．项目发起人、协调、依赖关系</li></ul><details class="quiz" data-q="6" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目整合管理由项目经理负责，项目整合管理的责任不能被授权或转移，项目经理必须对整个项目承担最终责任。整合是项目经理的一项关健技能（P237）　<span class="quiz-src">自编</span></p></details><p><a id="q7" class="quiz-anchor"></a></p><p><strong>7.</strong> 执行整合的层面不包括（ ）。</p><ul><li>A．过程层面</li><li>B．认知层面</li><li>C．背景层面</li><li>D．整体层面</li></ul><details class="quiz" data-q="7" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：执行整合的三个层面：&quot;1、过程层面执行整合项目管理过程中有些过程可能只发生一次，但很多过程在整个项目期间会相互重叠并重复发生多次&quot;2、认知层面执行整合项目经理应尽量熟练掌握所有项目管理知识领域，帮助项目经理将经验、见解、领导力、技术以及商业管理技能运用到项目管理中，并帮助项目经理整合这些知识领域所酒盖的过程，实现预期的项目结果（P237-238）　<span class="quiz-src">自编</span></p></details><p><a id="q8" class="quiz-anchor"></a></p><p><strong>8.</strong> 以下关于项目整合管理的叙述，正确的是（ ）。</p><ul><li>A．项目整合管理把各个管理过程看成是完全独立的</li><li>B．项目整合管理过程是线性的过程</li><li>C．项目整合管理是对项目管理过程组中的不同过程和活动进行识别、定义、整合、统一和协调的过程</li><li>D．项目整合管理不涉及成本估算过程</li></ul><details class="quiz" data-q="8" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「项目整合管理是对项目管理过程组中的不同过程和活动进行识别、定义、整合、统一和协调的过程」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q9" class="quiz-anchor"></a></p><p><strong>9.</strong> 随着新技术的不断涌现，社交网络、多元文化、虚拟团队和新的价值观等的出现，组织和项目所处的环境发生了很大变化。在执行并管理整合时，项目经理需要意识到项目背景和这些新因素，决定如何在项目中最好地利用这些新环境因素，以获得项目成功。这是属于（ ）</p><ul><li>A．背景层面执行整合</li><li>B．认知层面执行整合</li><li>C．过程层面执行整合</li><li>D．管理层面执行整合</li></ul><details class="quiz" data-q="9" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：执行整合的三个层面：1、过程层面执行整合项目管理过程中有些过程可能只发生一次，但很多过程在整个项目期间会相互重叠并重复发生多次（P237-238）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q10" class="quiz-anchor"></a></p><p><strong>10.</strong> 关于项目整合管理的描述，不正确的是（ ）。</p><ul><li>A．项目整合管理由项目经理负责，项目经理负责整合所有其他知识领域的成果，并擎握项目总体情况</li><li>B．执行项目整合时项目经理承担双重角色</li><li>C．项目整合管理的责任可由项目经理授权或转移</li><li>D．项目整合是项目经理的一项关键技能</li></ul><details class="quiz" data-q="10" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目整合管理由项目经理负责，项目经理负责整合所有其他知识领域的成果，并掌握项目总体情况。项目整合管理的责任不能被授权或转移，项目经理必须对整个项目承担最终责任（P237）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q11" class="quiz-anchor"></a></p><p><strong>11.</strong> 项目经理应尽量熟练掌握所有项目管理知识领域，帮助其将经验、见解、领导力、技术以及商业管理技能运用到项目管理中，体现了项目经理在（ ）的整合能力。</p><ul><li>A．认知层面</li><li>B．知识层面</li><li>C．过程层面</li><li>D．背景层面</li></ul><details class="quiz" data-q="11" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：认知层面执行整合；管理项目有多种方法，项目经理的人际关系技能和能力与其管理项目的方式紧密相关，方法的选择通常取决于项目的具体特点，包括规模、项目或组织的复杂性以及组织文化（P238）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q12" class="quiz-anchor"></a></p><p><strong>12.</strong> 作为项目的一种特征或属性，复杂性是指（ ）。①包含多个部分&quot;②不同部分之间存在差异性“③不同部分之间的动态交互作用④交互作用产生的行为远远大于各部分简单的相加</p><ul><li>A．①②③</li><li>B．②③④</li><li>C．①③④</li><li>D．①②③④</li></ul><details class="quiz" data-q="12" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目的复杂性来源于组织的系统行为、人类行为以及组织或环境中的不确定性。作为项目的一种特征或属性，复杂性的含义：①包含多个部分：②不回部分之间存在一系列关联；③不同部分之间的动态交互作用；④这些交互作用所产生的行为远远大于各部分简单的相加（例如突发性行为）（P238）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q13" class="quiz-anchor"></a></p><p><strong>13.</strong> 以下哪一项属于项目经理在项目内的职责（ ）。</p><ul><li>A．项目经理参与管理层和PMO负责的立项前的可行性研究与评估</li><li>B．项目经理参与结项后的效益管理</li><li>C．项目经理管理与各职能部门、运营部门和高级管理人员之间的接口</li><li>D．项目经理与团队成员一起讨论近段时间项目上出现的问题</li></ul><details class="quiz" data-q="13" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理在项目以外的职责：项目处在内外部环境中，项目经理需要参与管理层和PMO负责的立项前、结项后的可行性研究与评估和效益管理，以便更好地实现项目目标以及交付项目价值（P239）　<span class="quiz-src">自编</span></p></details><p><a id="q14" class="quiz-anchor"></a></p><p><strong>14.</strong> 以下不属于项目管理计划的是（ ）。</p><ul><li>A．项目生命周期描述</li><li>B．开发方法</li><li>C．范田基准</li><li>D．项目进度计划</li></ul><details class="quiz" data-q="14" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目管理计划：（范围、需求、进度、成本、质量、资源、沟通、风险、采购、干系人、变更、配置）管理计划。项目进度计划属于项目文性（P239）　<span class="quiz-src">自编</span></p></details><p><a id="q15" class="quiz-anchor"></a></p><p><strong>15.</strong> 下列不属于项目管理计划的是（ ）。</p><ul><li>A．项目生命周期描述</li><li>B．开发方法</li><li>C．绩效测量基准</li><li>D．团队章程</li></ul><details class="quiz" data-q="15" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目管理计划：（范围、需求、进度、成本、质量、资源、沟通、风险、采购、干系人、变更、配置）管理计划。团队章程属于项目文性（P239）　<span class="quiz-src">自编</span></p></details><p><a id="q16" class="quiz-anchor"></a></p><p><strong>16.</strong> 下面（ ）不属于项目管理计划的内容。</p><ul><li>A．范围管理计划</li><li>B．进度基准</li><li>C．采购管理计划</li><li>D．项目范围说明书</li></ul><details class="quiz" data-q="16" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目管理计划：（范围、需求、进度、成本、质量、资源、沟通、风险、采购、干系人、变更、配置）管理计划。项目范围说明书属于项目文件（P239）　<span class="quiz-src">自编</span></p></details><p><a id="q17" class="quiz-anchor"></a></p><p><strong>17.</strong> 关于项目管理计划的描述，不正确的是（ ）。</p><ul><li>A．项目管理计划包括项目范围说明书与质量测量指标</li><li>B．项目管理计划包括项目所选用的生命周期描述</li><li>C．项目管理计划包括范围基准、进度基准、成本基准</li><li>D．项目管理计划可以是概括的，也可以是详细的</li></ul><details class="quiz" data-q="17" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目范围说明书与质量测量指标属于项目文件（P239）　<span class="quiz-src">自编</span></p></details><p><a id="q18" class="quiz-anchor"></a></p><p><strong>18.</strong> 下列不属于项目文件的是（ ）。</p><ul><li>A．项目日历</li><li>B．问题日志</li><li>C．开发方法</li><li>D．项目进度计划</li></ul><details class="quiz" data-q="18" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：开发方法属于项目管理计划（P239）　<span class="quiz-src">自编</span></p></details><p><a id="q19" class="quiz-anchor"></a></p><p><strong>19.</strong> 下面属于项目管理计划的是（ ）</p><ul><li>A．项目进度计划</li><li>B．项目进度网络图</li><li>C．项目进度管理计划</li><li>D．里程碑图</li></ul><details class="quiz" data-q="19" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：只有项目进度管理计划是项目管理计划，其它都是项目文件（P239）　<span class="quiz-src">自编</span></p></details><p><a id="q20" class="quiz-anchor"></a></p><p><strong>20.</strong> 下列不属于项目文件的是（ ）</p><ul><li>A．质量报告</li><li>B．团队章程</li><li>C．绩效测量基准</li><li>D．项目进度计划</li></ul><details class="quiz" data-q="20" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：绩效测量基准属于项目管理计划（P239）　<span class="quiz-src">自编</span></p></details><p><a id="q21" class="quiz-anchor"></a></p><p><strong>21.</strong> 项目管理计划的内容不包括（ ）。</p><ul><li>A．沟通管理计划</li><li>B．生命周期模型</li><li>C．资源日历</li><li>D．成本基准</li></ul><details class="quiz" data-q="21" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：资源日历属于项目文件、（P239）　<span class="quiz-src">2018 年上半年高项</span></p></details><p><a id="q22" class="quiz-anchor"></a></p><p><strong>22.</strong> 关于项目管理计划的描述，不正确的是（ ）。</p><ul><li>A．项目管理计划是项目总体计划，它从整体上指导项目工作的有序进行</li><li>B．项目管理计划具有统筹作用，包括了项目管理与控制过程的所有文件</li><li>C．在项目管理信息系统中，项目管理计划在计划模块中制定和维护</li><li>D．项目管理计划可详可略，可由一个或多个部分计划及其他事项组成</li></ul><details class="quiz" data-q="22" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B错误。项目管理计划由十二个子计划和四大基准构成，不包含控制过程的文性（P239）　<span class="quiz-src">2022 年上半年高项</span></p></details><p><a id="q23" class="quiz-anchor"></a></p><p><strong>23.</strong> 项目管理过程中，会使用并产生项目管理计划和项目文件两大类文件。以下哪一个属于项目文件（ ）。</p><ul><li>A．开发方法</li><li>B．范围基准</li><li>C．成本估算</li><li>D．生命周期描述</li></ul><details class="quiz" data-q="23" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目管理计划包括：12个子管理计划、4个基准（范围、进度、成本、绩效测量基准）、个开发方法、1个生命周期描述、1个管理审查（P239）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q24" class="quiz-anchor"></a></p><p><strong>24.</strong> 对于项目整合管理，在整个项目期间开展的过程不包括（ ）。</p><ul><li>A．制订项目管理计划</li><li>B．指导与管理项目工作</li><li>C．管理项目知识</li><li>D．实施整体变更控制</li></ul><details class="quiz" data-q="24" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：制订项目管理计划仅开展一次或仅在项目的预定义时开展（P240）　<span class="quiz-src">教材第 8 章章节习题</span></p></details><p><a id="q25" class="quiz-anchor"></a></p><p><strong>25.</strong> 下列哪个过程在项目期间有且只开展一次（ ）。</p><ul><li>A．制定项目章程</li><li>B．指导与管理项目工作</li><li>C．管理项目知识</li><li>D．实施整体变更控制</li></ul><details class="quiz" data-q="25" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：制订项目章程仅开展一次或仅在项目的预定义时开展（P240）　<span class="quiz-src">自编</span></p></details><p><a id="q26" class="quiz-anchor"></a></p><p><strong>26.</strong> 下列哪个过程在项目期间有且只开展一次（ ）。</p><ul><li>A．制定项目管理计划</li><li>B．指导与管理项目工作</li><li>C．管理项目知识</li><li>D．实施整体变更控制</li></ul><details class="quiz" data-q="26" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：制定项目管理计划仅开展一次或仅在项目的预定义时开展（P240）　<span class="quiz-src">自编</span></p></details><p><a id="q27" class="quiz-anchor"></a></p><p><strong>27.</strong> 下列属于整合管理过程的是（ ）。</p><ul><li>A．获取知识</li><li>B．知识管理</li><li>C．估算活动</li><li>D．管理项目知识</li></ul><details class="quiz" data-q="27" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O。项目整合管理过程包括：①制定项目章程；②制订项目管理计划；③指导与管理项目工作④管理项目知识；⑤监控项目工作；⑥实施整体变更控制；⑦结束项目或阶段（P24）　<span class="quiz-src">自编</span></p></details><p><a id="q28" class="quiz-anchor"></a></p><p><strong>28.</strong> 在制定项目章程的过程中，关于章程制定活动描述不正确的是（ ）</p><ul><li>A．项目章程是证明项目存在的正式书面说明和证明文件</li><li>B．制定项目章程的活动可以在项目进展过程中持续完善或多次开展</li><li>C．项目章程规定了项目范围，如质量、时间、成本和可交付成果的约束条件</li><li>D．制定项目章程的主要作用为明确项目与组织战略目标之间的直接联系，确立项目的正式地位，并展示组织对项目的承诺</li></ul><details class="quiz" data-q="28" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：制定项目章程仅开展一次或仅在项目的预定义时开展（P240）　<span class="quiz-src">自编</span></p></details><p><a id="q29" class="quiz-anchor"></a></p><p><strong>29.</strong> 以下（ ）不属于整合管理的过程。</p><ul><li>A．制定项目章程</li><li>B．指导与管理项目工作</li><li>C．管理项目知识</li><li>D．识别干系人</li></ul><details class="quiz" data-q="29" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：识别干系人属于干系人管理的过程。项目整合管理过程包括：①制定项目章程；②制订项目管理计划；③指导与管理项目工作；④管理项目知识；⑤监控项目工作；⑥实施整体变更控制；⑦结束项目或阶段（P240-241）　<span class="quiz-src">2023 年下半年高项第 1 批</span></p></details><p><a id="q30" class="quiz-anchor"></a></p><p><strong>30.</strong> 以下内容，不属于整合管理领域活动的是（ ）。</p><ul><li>A．制定项目管理计划</li><li>B．控制项目整体风险</li><li>C．编制项目章程</li><li>D．管理项目知识</li></ul><details class="quiz" data-q="30" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目整合管理过程包括：①制定项目章程。②制订项目管理计划。③指导与管理项目工作④管理项目知识。⑤监控项目工作。⑥实施整体变更控制（P239-240）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q31" class="quiz-anchor"></a></p><p><strong>31.</strong> 每个项目都是独特的，所以项目经理根据需要裁剪项目整合管理过程，不需要考虑的因素是（ ）</p><ul><li>A．项目生命周期</li><li>B．开发生命周期</li><li>C．开发方法</li><li>D．知识管理</li></ul><details class="quiz" data-q="31" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：因为每个项目都是独特的，所以项目经理可能根据需要裁剪项目整合管理过程：(1)项目生命周期(2)开发生命周期(3)管理方法(4)知识管理(5)变更(6)治理(7)经验教训(8)效益（P241）　<span class="quiz-src">自编</span></p></details><p><a id="q32" class="quiz-anchor"></a></p><p><strong>32.</strong> 在整合管理中，（ ）不是裁剪考虑的因素。</p><ul><li>A．项目生命周期</li><li>B．知识管理</li><li>C．开发生命周期</li><li>D．监控</li></ul><details class="quiz" data-q="32" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：因为每个项目都是独特的，所以项目经理可能根据需要裁剪项目整合管理过程：(1)项目生命周期(2)开发生命周期(3)管理方法(4)知识管理(5)变更(6)治理(7)经验教训(8)效益（P241）　<span class="quiz-src">2023 年下半年高项第 1 批</span></p></details><p><a id="q33" class="quiz-anchor"></a></p><p><strong>33.</strong> 在敏捷或适应型环境中，以下说法不正确的是（ ）。</p><ul><li>A．项目团队会采用扁平化管理，项目经理主抓决策权</li><li>B．团队成员可以自行决定并控制具体产品的规划和交付</li><li>C．团队成员可以以相关领域专家的身份参与整合管理</li><li>D．项目经理重点关注营造合作型的决策氛围，并确保团队有能力应对变更</li></ul><details class="quiz" data-q="33" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：在敏捷或适应型环境中，柔用敏捷或适应型方法能够帮助项目经理将决策权下放，团队成员可以自行决定并控制具体产品的规划和交付，面项目经理则重点关注营造合作型的决策氛围，并确保团队有能力应对变更，促进团队成员以相关领域专家的身份参与整合管理（P241）　<span class="quiz-src">自编</span></p></details><p><a id="q34" class="quiz-anchor"></a></p><p><strong>34.</strong> 关于项目章程的描述，不正确的是（ ）。</p><ul><li>A．项目章程在项目执行组织与需求组织之间建立起伙伴关系</li><li>B．通过编制项目章程，来确认项目符合组织战略和日常运营的需要</li><li>C．项目章程可替代合同</li><li>D．项目章程授权项目经理规划、执行和控制项目</li></ul><details class="quiz" data-q="34" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目章程不能当作合同，项目章程用于建立组织内部的合作关系，确保正确交付合同内容（P242）　<span class="quiz-src">教材第 8 章章节习题</span></p></details><p><a id="q35" class="quiz-anchor"></a></p><p><strong>35.</strong> 项目章程用于（ ），确保正确交付合同内容。</p><ul><li>A．任命项目经理</li><li>B．建立组织内部的合作关系</li><li>C．启动项目</li><li>D．分配资源</li></ul><details class="quiz" data-q="35" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目章程不能当作合同，在执行外部项目时，通常需要用正式的合同来达成合作协议，项目章程用于建立组织内部的合作关系，确保正确交付合同内容（P242）　<span class="quiz-src">自编</span></p></details><p><a id="q36" class="quiz-anchor"></a></p><p><strong>36.</strong> 制定项目章程的作用不包括（ ）。</p><ul><li>A．明确项目与组织战略目标之间的直接联系</li><li>B．确立项目的正式地位</li><li>C．展示组织对项目的承诺</li><li>D．给项目经理授权</li></ul><details class="quiz" data-q="36" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：制定项目章程的作用：①明确项目与组织战略目标之间的直接联系；②确立项目的正式地位③展示组织对项目的承谐（P242）　<span class="quiz-src">自编</span></p></details><p><a id="q37" class="quiz-anchor"></a></p><p><strong>37.</strong> 关于项目章程的作用和内容的描述，以下不正确的是（ ）。</p><ul><li>A．在执行外部项目时，通常需要用正式的合同来达成合作协议，此时不需要用项目章程来建立组织内部的合作关系</li><li>B．项目章程一旦被批准，就标志着项目的正式启动</li><li>C．项目应尽早确认并任命项目经理，最好在制定项目章程时就任命</li><li>D．项目章程授权项目经理规划、执行和控制项目</li></ul><details class="quiz" data-q="37" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目章程不能当作合同，在执行外部项目时，通常需要用正式的合同来达成合作协议，项目章程用于建立组织内部的合作关系，确保正确交付合同内容（P242）　<span class="quiz-src">自编</span></p></details><p><a id="q38" class="quiz-anchor"></a></p><p><strong>38.</strong> 关于制定项目章程过程及相关描述，正确的是（ ）。①制定项目章程是编写正式批准项目并授权项目经理使用组织资源的文件的过程②项目章程可当作合同使用，用于外部项目的合作协议达成“③项目章程一旦被批准，就标志着项目正式启动④应在规划开始之后任命项目经理，确保规划工作有序推进⑤项目章程可由发起人编制，也可由项目经理与发起机构合作编制</p><ul><li>A．①③⑤</li><li>B．①②⑤</li><li>C．②③⑤</li><li>D．①③④</li></ul><details class="quiz" data-q="38" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：制定项目章程是编写一份正式批准项目并授权项目经理在项目活动中使用组织资源的文件的过程。项目章程不能当作合同，在执行外部项目时，通常需要用正式的合同来达成合作协议项目草程用于建立组织内部的合作关系（P242）　<span class="quiz-src">自编</span></p></details><p><a id="q39" class="quiz-anchor"></a></p><p><strong>39.</strong> 某公司计划后动一个新的内部管理系统开发项目，发起人已完成立项论证，确定了项目的商业需求和成本效益分析，现在需要确立项目的正式地位。针对该场景，当前最关键的工作是（ ）</p><ul><li>A．签订正式合同</li><li>B．制定项目章程</li><li>C．识别关键干系人</li><li>D．编制项目管理计划</li></ul><details class="quiz" data-q="39" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：选项A:该项目为内部项目，无需签订外部合同，合同主要用于外部项目的合作协议达成，因此A不合适。选项B:制定项目章程是编写正式批准项目并授权项目经理使用组织资源的文件的过程，当前场景下，发起人已完成立项论证，最关键的工作就是制定项目章程，确立项目正式地位并授权项目经理，该做法最关键（P242）　<span class="quiz-src">自编</span></p></details><p><a id="q40" class="quiz-anchor"></a></p><p><strong>40.</strong> （ ）不是制定项目章程的输入。</p><ul><li>A．立项管理文件</li><li>B．协议</li><li>C．合同或谅解备忘录协议</li><li>D．项目成功标准</li></ul><details class="quiz" data-q="40" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目成功标准是项目章程里的内容制定项目章程的输入有：1立项管理文件；2.协议(合同、凉解备忘录(MOUs)、服务水平协议(SLA)、协议书、意向书、口头协议成其他书面协议);3事业环境因素；4组织过程资产（P242-243）　<span class="quiz-src">自编</span></p></details><p><a id="q41" class="quiz-anchor"></a></p><p><strong>41.</strong> （ ）不是影响制定项目章程过程的环境和组织因素。</p><ul><li>A．政府或行业标准</li><li>B．组织的基础设施</li><li>C．市场条件</li><li>D．合同</li></ul><details class="quiz" data-q="41" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：能够影响制定项目章程过程的事业环境因素主要包括：政府或行业标准（如产品标准、质量标准、安全标准和工艺标准）;法律法规要求和相关制约因素；市场条件；组织文化和氛围：组织治理框架（通过安排人员、制定政策和确定过程，以结构化的方式实施控制、指导和协调，以实现组织的战略和目标）;干系人的期望和风险临界值等（P243）　<span class="quiz-src">自编</span></p></details><p><a id="q42" class="quiz-anchor"></a></p><p><strong>42.</strong> 关于立项管理文件的描述，不正确的是（ ）。</p><ul><li>A．立项管理包含商业需求和成本效益分析</li><li>B．立项管理文件也是项目文件的一种，需要妥善保管</li><li>C．虽然立项管理文件是在项目之前制定的，但需要定期审核</li><li>D．立项管理文件是甲方订立的，所以项目经理不可以对它们进行更新或修改</li></ul><details class="quiz" data-q="42" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：立项管理包含商业需求和成本效益分析，由于立项管理文件不是项目文件，项目经理不可以对它们进行更新或修改，只可以提出相关建议（P243）　<span class="quiz-src">自编</span></p></details><p><a id="q43" class="quiz-anchor"></a></p><p><strong>43.</strong> 在制定项目章程时，（ ）有助于在短时间内获得大量创意，适用于团队环境，需要引导者引导</p><ul><li>A．冲突管理</li><li>B．访谈</li><li>C．会议管理</li><li>D．头脑风暴</li></ul><details class="quiz" data-q="43" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：头脑风紧：在短时间内获得大量创意，适用于团队环境，需要引导者引导。包括：创意产生和创意分析两个部分（P243-244）　<span class="quiz-src">自编</span></p></details><p><a id="q44" class="quiz-anchor"></a></p><p><strong>44.</strong> 在制定项目章程时，召集干系人和主题专家讨论议题，比一对一访谈更有利于互动交流，属于数据收集技术中的（ ）。</p><ul><li>A．冲突管理</li><li>B．焦点小组</li><li>C．会议管理</li><li>D．头脑风暴</li></ul><details class="quiz" data-q="44" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：焦点小组：召集干系人和主题专家讨论议题，比一对一访谈更有利于互动交流（P243-244）　<span class="quiz-src">自编</span></p></details><p><a id="q45" class="quiz-anchor"></a></p><p><strong>45.</strong> 项目章程的主要内容包括（ ）。①可测量的项目目标和相关的成功标准②高层级需求、高层级项目描述、边界定义以及主要可交付成果&quot;③总体里程碑进度计划④整体项目风险5项目范围说明书⑥项目成本基准</p><ul><li>A．①②③⑥</li><li>B．①②③④</li><li>C．①③④⑤</li><li>D．①④⑤⑥</li></ul><details class="quiz" data-q="45" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目章程包含内容：①项目目的；②可测量的项目目标和相关的成功标准；③高层级需求、高层级项目描述、边界定义以及主要可交付成果；④整体项目风险；⑤总体里程碑进度计划；⑥预先批准的财务资源；⑦关键干系人名单；⑥项目审批要求；⑥项目退出标准；00委派的项目经理及其职责和职权；①发起人成其他批准项目章程的人员的姓名和职权等（P244）　<span class="quiz-src">自编</span></p></details><p><a id="q46" class="quiz-anchor"></a></p><p><strong>46.</strong> 下面（ ）不属于项目章程的内容。</p><ul><li>A．委派的项目经理及其职责和职权</li><li>B．发起人或其他批准项目章程的人员的姓名和职权</li><li>C．项目团队成员名单</li><li>D．可测量的项目目标和相关的成功标准</li></ul><details class="quiz" data-q="46" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目章程包含内容：①项目目的；②可测量的项目目标和相关的成功标准；③高层级需求、高层级项目描述、边界定义以及主要可交付成果；④整体项目风险；⑤总体里程碑进度计划：⑥预先批准的财务资源：⑦关键王系人名单：⑥项目重批要求；③项目温出标准；①委派的项目经理及其职责和职权；D发起人或其他批准项目章程的人员的姓名和职权等（P244）　<span class="quiz-src">自编</span></p></details><p><a id="q47" class="quiz-anchor"></a></p><p><strong>47.</strong> 下面（ ）不属于项目章程的内容。</p><ul><li>A．委派的项目经理及其职责和职权</li><li>B．详细的项目进度计划</li><li>C．发起人或其他批准项目章程的人员的姓名和职权</li><li>D．可测量的项目目标和相关的成功标准</li></ul><details class="quiz" data-q="47" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目章程包含内容：①项目目的；②可测量的项目目标和相关的成功标淮；③高层级需求、高层级项目描述、边界定义以及主要可交付成果；④整体项目风险；⑤总体里程碑进度计划：③预先批准的财务资源；⑦关键干系人名单：⑥项目审批要求；③项目退出标准；①委派的项目经理及其职责和职权；Q0发起人或其他批准项目章程的人员的姓名和职权等（P244）　<span class="quiz-src">自编</span></p></details><p><a id="q48" class="quiz-anchor"></a></p><p><strong>48.</strong> （ ）用于记录整个项目生命周期中的所有假设条件和制约因素。</p><ul><li>A．问题日志</li><li>B．假设日志</li><li>C．变更日志</li><li>D．项目管理计划</li></ul><details class="quiz" data-q="48" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：假设日志用王记录整个项目生命周期中的所有假设条件和制约因素，在项目启动之前进行可行性研究和论证时，即开始识别高层级的战略和运营假设条件与制约因素（P245）　<span class="quiz-src">自编</span></p></details><p><a id="q49" class="quiz-anchor"></a></p><p><strong>49.</strong> 关于项目章程的描述，不正确的是（ ）。</p><ul><li>A．项目章程通常由高级管理层签发</li><li>B．项目章程一旦被批准，就标志着项目的正式启动</li><li>C．项目章程在项目执行组织与需求组织之间建立起伙伴关系。通过编制项目章程，来确认项目是否符合组织战略和日常运营的需要</li><li>D．项目经理有权修改项目章程</li></ul><details class="quiz" data-q="49" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「项目经理有权修改项目章程」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q50" class="quiz-anchor"></a></p><p><strong>50.</strong> 某项目经理高洋所在的单位正在启动一个新的项目，配备了虚拟项目小组，根据过去的经验，该项目经理认识到矩阵环境下的小组成员有时对职能经理的配合超过对项目经理的配合，因此，该项目经理决定请求单位制定（ ）。</p><ul><li>A．项目计划</li><li>B．项目章程</li><li>C．项目范围说明书</li><li>D．人力资源管理计划</li></ul><details class="quiz" data-q="50" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：课本无原话。“1、项目章程用于建立组织内部的合作关系，确保正确交付合同内容　<span class="quiz-src">自编</span></p></details><p><a id="q51" class="quiz-anchor"></a></p><p><strong>51.</strong> 对于项目章程相关内容的描述不正确的是（ ）。</p><ul><li>A．项目章程可由发起人编制，也可由项目经理与发起机构合作编制</li><li>B．在执行外部项目时，通常需要用项目章程来达成合作协议</li><li>C．项目章程一旦被批准，就标志着项目的正式启动</li><li>D．项目经理越早确认并任命越好，最好在制定项目章程时就任命</li></ul><details class="quiz" data-q="51" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目章程不能当作合同，在执行外部项目时，通常需要用正式的合同来达成合作协议，项目章程用于建立组织内部的合作关系，确保正确交付合同内容（P242）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q52" class="quiz-anchor"></a></p><p><strong>52.</strong> 以下关于项目章程的概述中，正确的是（ ）。</p><ul><li>A．项目章程与合同内容是一致的</li><li>B．项目章程要由项目经理发布</li><li>C．项目章程要明确项目在组织中的地位</li><li>D．项目章程就是一个程序文件</li></ul><details class="quiz" data-q="52" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：制定项目章程是编写一份正式批准项目并授权项目经理在项目活动中使用组织资源的文件的过程。本过程的主要作用：①明确项目与组织战监目标之间的直接联系；②确立项目的正式地位；③展示组织对项目的承诺、　<span class="quiz-src">2016 年下半年高项</span></p></details><p><a id="q53" class="quiz-anchor"></a></p><p><strong>53.</strong> 通常在（ ）任命项目经理比较合适。</p><ul><li>A．可研过程之前</li><li>B．签订合同之前</li><li>C．招投标之前</li><li>D．开始制定项目计划前</li></ul><details class="quiz" data-q="53" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：课本无原话。A错误。这个时候项目都还没立项。B错误。这个时候承建方还未确定。C错误。这个时候承建方还未确定。D正确。在制订项目管理计划之前，需要先制定项目章程，这个时候任命项目经理P242　<span class="quiz-src">2017 年上半年高项</span></p></details><p><a id="q54" class="quiz-anchor"></a></p><p><strong>54.</strong> 关于项目管理计划的描述，不正确的是（ ）。</p><ul><li>A．头脑风暴、冲突处理和会议管理可帮助项目管理计划的制定</li><li>B．项目章程由项目经理签字，是编制项目管理计划的依据之一</li><li>C．项目经理不能理想化期望项目管理计划一步到位</li><li>D．组织的过程测量数据库也可以是项目管理计划制定的依据</li></ul><details class="quiz" data-q="54" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：课本无原话。选项A正确：头脑风暴可收集多方意见，冲突处理能化解计划制定中的分歧，会议管理可高效推进计划编制，这些方法均能助力项目管理计划制定选项B错误：项目章程是由项目发起人或高级管理层签字批准，而非项目经理　<span class="quiz-src">2021 年下半年高项</span></p></details><p><a id="q55" class="quiz-anchor"></a></p><p><strong>55.</strong> 在制定项目章程需要的人际关系与团队技能中，（ ）有助于干系人就目标、成功标准、高层级需求、项目描述、总体里程碑和其他内容达成一致意见。</p><ul><li>A．冲突管理</li><li>B．访谈</li><li>C．会议管理</li><li>D．头脑风暴</li></ul><details class="quiz" data-q="55" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：制定项目章程需要的人际关系与团队技能主要包括：“1、冲突管理：有助于干系人就目标、成功标准、高层级需求、项目描述、总体里程理和其他内容达成一致意见（P244）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q56" class="quiz-anchor"></a></p><p><strong>56.</strong> 以下（ ）不是项目章程的内容。</p><ul><li>A．项目目的</li><li>B．范围基准</li><li>C．高层级需求</li><li>D．项目退出标准</li></ul><details class="quiz" data-q="56" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目章程记录了关于项目和项目预期交付的产品、服务或成果的高层级信息：①项目目的②可测量的项目目标和相关的成功标准；③高层级需求、高层级项目描述、边界定义以及主要可交付成果；④整体项目风险；⑤总体里程碑进度计划；⑥预先批准的财务资源；⑦关键干系人名单；⑥项目审批要求（例如，评价项目成功的标准，由谁对项目成功下结论，由谁签署项目结来）;③项目退出标准（例如，在何种条件下才能关闭或取消项目或阶段）;①委…（P244）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q57" class="quiz-anchor"></a></p><p><strong>57.</strong> 以下属于制定项目章程的输入的是（ ）。①商业需求；②可交付成果；③协议；④经验教训登记册；⑤成本效益分析</p><ul><li>A．②③④</li><li>B．①②③</li><li>C．①③⑤</li><li>D．①②④</li></ul><details class="quiz" data-q="57" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「①③⑤」，原解析未给课本依据　<span class="quiz-src">2023 年下半年高项第 3 批</span></p></details><p><a id="q58" class="quiz-anchor"></a></p><p><strong>58.</strong> 项目章程可由发起人编制，也可由项目经理与（ ）合作编制。通过这种合作，项目经理可以更好地了解项目的目的、目标和预期收益，以便更有效地分配项目资源。</p><ul><li>A．发起机构</li><li>B．评估机构</li><li>C．客户</li><li>D．干系人</li></ul><details class="quiz" data-q="58" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目章程可由发起人编制，也可由项目经理与发起机构合作编制（P242）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q59" class="quiz-anchor"></a></p><p><strong>59.</strong> 关于项目章程的描述，不正确的是（ ）。</p><ul><li>A．项目章程中需明确高层级的里程碑计划，但详细资源分配应在后续规划阶段完成</li><li>B．项目章程用于建立组织内部的合作关系，确保正确交付合同内容</li><li>C．立项管理文件属于项目文件，制定项目章程时项目经理可以根据需要对其变更</li><li>D．项目章程可由发起人编制，也可由项目经理与发起机构合作编制</li></ul><details class="quiz" data-q="59" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：由于立项管理文件不是项目文件，项目经理不可以对它们进行更新或修改，只可以提出相关建议。虽然立项管理文件是在项目之前制定的，但需要定期审核（P243）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q60" class="quiz-anchor"></a></p><p><strong>60.</strong> 以下（ ）不属于项目章程的内容。</p><ul><li>A．退出标准</li><li>B．行业标准</li><li>C．审批要求</li><li>D．项目风险</li></ul><details class="quiz" data-q="60" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：能够影响制定项目章程过程的事业环境因素主要包括：政府或行业标准（如产品标准、质量标准、安全标准和工艺标准）;法律法规要求和相关制约因素；市场条件；组织文化和氛围；组织治理框聚（通过安排人员、制定政策和确定过程，以结构化的方式实施控制、指导和协调，以实现组织的战略和目标）;干系人的期望和风险临界值等（P243）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q61" class="quiz-anchor"></a></p><p><strong>61.</strong> 关于项目管理计划的理解，不正确的是（ ）。</p><ul><li>A．项目管理计划确定项目的执行、监控和收尾方式，其内容会因项目所在的应用领域和复杂程度而异</li><li>B．项目管理计划需详细制订，每个组成部分的详细程度取决于具体项目要求</li><li>C．项目管理计划应基准化，至少应规定项目的范围、时间和成本方面的基准</li><li>D．在确定基准之前，可能要对项目管理计划进行多次更新</li></ul><details class="quiz" data-q="61" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B不正确。项目管理计划可以是高度概括的或详细的（P245）　<span class="quiz-src">教材第 8 章章节习题</span></p></details><p><a id="q62" class="quiz-anchor"></a></p><p><strong>62.</strong> 关于项目管理计划的理解，不正确的是（ ）。</p><ul><li>A．项目管理计划确定项目的执行、监控和收尾方式，其内容会因项目所在的应用领域和复杂程度而异</li><li>B．在项目收尾之前，项目管理计划需要通过不断更新来渐进明细</li><li>C．项目管理计划应基准化，至少应规定项目的范围、时间和成本方面的基准</li><li>D．在确定基准之前，可能要对项目管理计划进行多次更新，需要实施整体变更控制过程进行控制</li></ul><details class="quiz" data-q="62" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：D不正确。在确定基准之前，可能要对项目管理计划进行多次更新，且这些更新无需遵循正式的流程（P245）　<span class="quiz-src">自编</span></p></details><p><a id="q63" class="quiz-anchor"></a></p><p><strong>63.</strong> 关于项目管理计划的描述，下列说法正确的是（ ）。</p><ul><li>A．项目管理计划的详细程度固定，与项目应用领域和复杂程度无关</li><li>B．确定项目基准前，更新项目管理计划需遵循正式变更流程</li><li>C．项目管理计划基准至少应包含范围、时间和成本三个方面，基准确定后需通过变更请求流程更新</li><li>D．项目收尾前，项目管理计划无需更新，仅需按最终版本执行</li></ul><details class="quiz" data-q="63" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：选项A错误：项目管理计划可以是概括或详细的，每个组成部分的详细程度取决于具体项目的要求选项B错误：在确定基准之前，可能要对项目管理计划进行多次更新，且这些更新无需遵循止式的流程（P245）　<span class="quiz-src">自编</span></p></details><p><a id="q64" class="quiz-anchor"></a></p><p><strong>64.</strong> 制订项目管理计划过程的人际关系与团队技能不包括（ ）。</p><ul><li>A．冲突管理</li><li>B．引导</li><li>C．会议管理</li><li>D．访谈</li></ul><details class="quiz" data-q="64" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：制订项目管理计划需要的人际关系与团队技能主要包括●冲突管理：必要时可以通过冲突管理让具有差异性的干系人就项目管理计划的所有方面达战共识（P247）　<span class="quiz-src">自编</span></p></details><p><a id="q65" class="quiz-anchor"></a></p><p><strong>65.</strong> 通常由项目管理团队开展大部分规划工作。在初始规划工作完成、执行（开发）阶段开始时，项目团队其他成员才参与进来。这种情况下，开工会议将在项目执行阶段开始时召开。这种适用于（ ）。</p><ul><li>A．小型项目</li><li>B．大型项目</li><li>C．多阶段项目</li><li>D．选代型项目</li></ul><details class="quiz" data-q="65" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：开工会议召开时机取决于项目特征：对于小型项目：通常由同一个团队开展项目规划和执行。这种情况下，由于执行团队参与了规划，项目在启动之后就会开工（P247）　<span class="quiz-src">自编</span></p></details><p><a id="q66" class="quiz-anchor"></a></p><p><strong>66.</strong> 制订项目管理计划过程的输入不包括（ ）。</p><ul><li>A．项目章程</li><li>B．需求管理计划</li><li>C．活动清单</li><li>D．范围管理计划</li></ul><details class="quiz" data-q="66" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：制定项目管理计划的输入包括：1项目章程；2.其他知识领域规划过程的输出；3事业环境因素；4.组织过程资产。创建项目管理计划需要整合诸多过程的输出（P246）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q67" class="quiz-anchor"></a></p><p><strong>67.</strong> 以下关于项目管理计划编制的理解中，正确的是（ ）。</p><ul><li>A．项目经理应组织并主要参与项目管理计划的编制，但不应独立编制</li><li>B．项目管理计划的编制不能采用迭代的方法</li><li>C．让项目干系人参与项目计划的编制，增加了沟通成本，应尽量避免</li><li>D．项目管理计划不能是概括的，应该是详细、具体的</li></ul><details class="quiz" data-q="67" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「项目经理应组织并主要参与项目管理计划的编制，但不应独立编制」，原解析未给课本依据　<span class="quiz-src">2016 年上半年高项</span></p></details><p><a id="q68" class="quiz-anchor"></a></p><p><strong>68.</strong> 项目经理张工带领团队编制项目管理计划，（ ）不属于编制项目管理计划过程的依据。</p><ul><li>A．项目章程</li><li>B．事业环境因素</li><li>C．组织过程资产</li><li>D．工作分解结构</li></ul><details class="quiz" data-q="68" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：制定项目管理计划的输入包括：1项目章程；2.其他知识领域规划过程的输出；3.事业环境因素；4.组织过程资产（P246）　<span class="quiz-src">2017 年下半年高项</span></p></details><p><a id="q69" class="quiz-anchor"></a></p><p><strong>69.</strong> 能够影响“制订项目管理计划”过程的组织过程资产包括（ ）①组织的标准政策②变更控制程序&quot;③历史项目进度网络图④特定行业的项目管理知识体系⑤法律法规和安全标准⑥历史信息和经验教训知识库</p><ul><li>A．①②③⑥</li><li>B．①③⑤⑥</li><li>C．①③④⑥</li><li>D．①②④⑤</li></ul><details class="quiz" data-q="69" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：能够影响制订项目管理计划过程的组织过程资产主要包括：组织的标准政策、流程和程序；项目管理计划模板变更控制程序，包括修改正式的组织标准、政策、计划、程序或项目文件，以及批准和确认变更所须遵循的步骤；监督和报告方法、风险控制程序以及沟通要求；以往类似项目的相关信息（如范围、成本、进度与绩效测量基准、项目日历、项目进度园络图和风险登记册）;历史信息和经验教训知识库等（P246）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q70" class="quiz-anchor"></a></p><p><strong>70.</strong> （ ）是为实现项目目标而领导和执行项目管理计划中所确定的工作，并实施已批准变更的过程</p><ul><li>A．制定项目管理计划</li><li>B．制定项目章程</li><li>C．指导与管理项目工作</li><li>D．监控项目工作</li></ul><details class="quiz" data-q="70" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：指导与管理项目工作是为实现项目目标面领导和执行项目管理计划中所确定的工作，并实施已批准变更的过程（P251）　<span class="quiz-src">自编</span></p></details><p><a id="q71" class="quiz-anchor"></a></p><p><strong>71.</strong> 关于实施整体变更控制的描述，不正确的是（ ）。</p><ul><li>A．项目经理对实施整体变更过程负最终责任</li><li>B．如遇特殊情况，变更请求可以口头提出</li><li>C．变更日志用来记录项目过程中出现的变更</li><li>D．项目经理不可以加入变更控制委员会</li></ul><details class="quiz" data-q="71" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：CCB是项目的所有者权益代表，负责对变更进行决策。CCB由项目所涉及的主要干系人共同组成，通常包括用户和项目所在组织管理层的决策人员（P252）　<span class="quiz-src">自编</span></p></details><p><a id="q72" class="quiz-anchor"></a></p><p><strong>72.</strong> 指导与管理项目工作的输入包括（ ），它是实施整体变更控制过程的输出，必要时需经（ ）审查和批准，其中（ ）是决策机构，不是作业机构。</p><ul><li>A．批准的变更请求、CCB、CCB</li><li>B．可交付成果、项目经理、项目经理</li><li>C．工作绩效数据、CCB、项目经理</li><li>D．变更请求、项目经理、CCB</li></ul><details class="quiz" data-q="72" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：指导与管理项目工作的输入包括批准的变更请求，它是实施整体变更控制过程的输出，包括经项目经理审查和批准的变更请求，必要时需要经变更控制委员会(CCB)审查和批准（P252）　<span class="quiz-src">自编</span></p></details><p><a id="q73" class="quiz-anchor"></a></p><p><strong>73.</strong> 关于可交付成果的理解，不正确的是（ ）。</p><ul><li>A．可交付成果是在某一过程、阶段或项目完成时，必须产出的任何独特并可核实的产品成果或服务能力</li><li>B．可交付成果包含项目管理计划中的组成部分</li><li>C．可交付成果完成后，如需变更，只要不涉及基准，可以不执行变更控制，但是如果涉及基准，那么就需要执行变更控制</li><li>D．用配置管理工具和程序来支持对可交付成果的多个版本的控制</li></ul><details class="quiz" data-q="73" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：可交付成果是在某一过程、阶段或项目完成时，必须产出的任何独特并可核实的产品、成果或服务能力。它通常是项目的结果，包括项目管理计划的组成部分一且完成了可交付成果的第一个版本，就应该执行变更控制（P253）　<span class="quiz-src">自编</span></p></details><p><a id="q74" class="quiz-anchor"></a></p><p><strong>74.</strong> 以下说法正确的是（ ）。</p><ul><li>A．CCB是作业机构，不是决策机构</li><li>B．可交付成果包含项目管理计划中的组成部分</li><li>C．可交付成果完成后，如需变更，只要不涉及基准，可以不执行变更控制，但是如果涉及基准，那么就需要执行变更控制</li><li>D．先进的虚拟互动技术最有利于建立知识管理所需的信任关系</li></ul><details class="quiz" data-q="74" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：可交付成果是在某一过程、阶段或项目完成时，必须产出的任何独特并可核实的产品、成果或服务能力。它通常是项目的结果，包括项目管理计划的组成部分（P253）　<span class="quiz-src">自编</span></p></details><p><a id="q75" class="quiz-anchor"></a></p><p><strong>75.</strong> 关于工作绩效数据的描述，正确的是（ ）。</p><ul><li>A．产生于监控项目工作过程</li><li>B．用于记录项目执行情况</li><li>C．定期或特殊需要时产生</li><li>D．其内容包括识别范围的偏差与原因</li></ul><details class="quiz" data-q="75" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：工作绩效数据是在执行项目工作的过程中，从每个正在执行的活动中收集到的原始观察结果和测量值，用于记录项目执行情况，其内容包括收到的变更请求的数量等（P253）　<span class="quiz-src">自编</span></p></details><p><a id="q76" class="quiz-anchor"></a></p><p><strong>76.</strong> 指导与管理项目工作过程的输出包括（ ）。①可交付成果；②工作绩效数据；③批准的变更请求；④项目文件更新</p><ul><li>A．①③④</li><li>B．①②④</li><li>C．②③④</li><li>D．①②③</li></ul><details class="quiz" data-q="76" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：批准的变更请求是指导与管理项目工作的输入，而不是输出。指导与管理项目工作过程的输出包括：1可交付成果；2.工作绩效数据；3问题日志；4.变更请求；5项目管理计划（更新）6.项目文件（更新）;7.组织过程资产（更新）（P253-254）　<span class="quiz-src">自编</span></p></details><p><a id="q77" class="quiz-anchor"></a></p><p><strong>77.</strong> 为确保项目工作的未来绩效符合项目管理计划，而进行的有目的活动属于（ ）。</p><ul><li>A．缺陷补救</li><li>B．纠正措施</li><li>C．修复措施</li><li>D．预防措施</li></ul><details class="quiz" data-q="77" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：预防措施：为确保项目工作的未来绩效符合项目管理计划，进行的有目的活动（P254）　<span class="quiz-src">自编</span></p></details><p><a id="q78" class="quiz-anchor"></a></p><p><strong>78.</strong> 项目进入到执行阶段后，项目经理、项目组成员为了完成项目范围说明书定义的工作，还需执行的是（ ）。①实施已批准的预防措施以降低潜在负面结果出现的可能性②管理已分配到项目或阶段中的项目团队成员&quot;③为项目选择生命周期模型&quot;④监管项目总投入情况⑤管理供应商</p><ul><li>A．①②⑤</li><li>B．①②③④</li><li>C．①②④⑤</li><li>D．①②③④⑤</li></ul><details class="quiz" data-q="78" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「①②⑤」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q79" class="quiz-anchor"></a></p><p><strong>79.</strong> （ ）属于工作绩效数据的内容。</p><ul><li>A．识别范围的偏差与原因</li><li>B．偏差的进度与成本的影响</li><li>C．范围绩效的测试</li><li>D．收到的变更请求的数量</li></ul><details class="quiz" data-q="79" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：工作绩效数据包括已完成的工作、关键绩效指标(KPI)、技术绩效测量结果、进度活动的实际开始日期和完成日期、已完成的故事点、可交付成果状态、进度进展情况、变更请求的数量、缺陷的数量、实际发生的成本和实际持续时间等（P253）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q80" class="quiz-anchor"></a></p><p><strong>80.</strong> 关于工作绩效数据的描述，正确的是（ ）。</p><ul><li>A．项目团队和发起人使用</li><li>B．定期或特殊需要时产生</li><li>C．用于记录项目执行情况</li><li>D．产生于监控项目工作过程</li></ul><details class="quiz" data-q="80" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：工作绩效数据是在执行项目工作的过程中，从每个正在执行的活动中收集到的原始观察结果和测量值。数据通常是最低层次的细节，将交由其他过程从中提炼并形成信息（P253）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q81" class="quiz-anchor"></a></p><p><strong>81.</strong> 关于指导和管理项目工作的描述，不正确的是（ ）。</p><ul><li>A．通过跟踪、审查和报告整体项目进展</li><li>B．作用是对项目工作和可交付成果开展综合管理，以提高项目成功的可能性</li><li>C．是为实现项目目标而领导和执行项目管理计划中所确定的工作</li><li>D．包括执行项目管理计划的各种项目活动</li></ul><details class="quiz" data-q="81" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：描述的是监控项目工作　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q82" class="quiz-anchor"></a></p><p><strong>82.</strong> 指导与管理项目工作的输出不包括（ ）。</p><ul><li>A．工作绩效报告</li><li>B．可交付成果</li><li>C．问题日志</li><li>D．变更请求</li></ul><details class="quiz" data-q="82" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：指导与管理项目工作的主要输出包括：1可交付成果；2.工作绩效数据；3问题日志；4变更请求（P253-254）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q83" class="quiz-anchor"></a></p><p><strong>83.</strong> 在接到一涉密系统集成项目后，项目经理离牛要求信息技术部按公司规定，为每个项目组成员配置并安装数据防泄露工具的笔记本电脑，该项目经理采用的是（ ）。</p><ul><li>A．批准的纠正措施</li><li>B．批准的预防措施</li><li>C．批准的缺陷补救措施</li><li>D．批准的变更请求</li></ul><details class="quiz" data-q="83" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：纠正措施：为使项目工作绩效重新与项目管理计划一致而进行的有目的活动。预防措施：为确保项目工作的未来绩效符合项目管理计划而进行的有目的活动缺陷补救：为了修正不一致的产品或产品组件而进行的有目的活动（P254）　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q84" class="quiz-anchor"></a></p><p><strong>84.</strong> （ ）属于工作绩效数据。①关键绩效指标(KP1);②挣值分析；③进度活动的实际开始日期；④可交付成果状态；6合同绩效信息；⑥缺陷的数量</p><ul><li>A．①②③④</li><li>B．①3④⑥</li><li>C．②③⑤6</li><li>D．③④⑤⑥</li></ul><details class="quiz" data-q="84" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：工作绩效数据是在执行项目工作的过程中，从每个正在执行的活动中收集到的原始观察结果和测量值。数据通常是最低层次的细节，在工作执行过程中收集数据，再交由10大知识领域的相应的控制过程做进一步分析（P253）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q85" class="quiz-anchor"></a></p><p><strong>85.</strong> 在监控项目工作过程中，当遇到变更请求时，为使项目工作绩效重新与项目管理计划一致，而进行的有目的活动属于（ ）。</p><ul><li>A．纠正措施</li><li>B．评审措施</li><li>C．预防措施</li><li>D．缺陷补救</li></ul><details class="quiz" data-q="85" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：变更请求一般包括：纠正措施：为使项目工作绩效重新与项目管理计划一致而进行的有目的活动。预防措施：为确保项目工作的未来绩效符合项目管理计划而进行的有目的活动缺陷补救：为了修正不一致的产品或产品组件而进行的有目的活动更新：对正式受控的项目文件或计划进行变更，以反映修改、增加的意见或内容（P254）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q86" class="quiz-anchor"></a></p><p><strong>86.</strong> 关于项目实施整体变更控制的描述不正确的是（ ）。</p><ul><li>A．影响项目基准的变更应由CCB和客户审批</li><li>B．项目经理对实施变更控制过程承担最终责任</li><li>C．CCB也可以审查配置管理活动，应明确规定CCB的角色和职责</li><li>D．批准的变更请求都是可用于实施整体变更控制过程的输入文件</li></ul><details class="quiz" data-q="86" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：252。批准的变更请求是实施整体变更控制过程的输出，所以D不正确　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q87" class="quiz-anchor"></a></p><p><strong>87.</strong> 关于项目整合管理的描述不正确的是（ ）。</p><ul><li>A．批准的变更请求可能导致修改正式受控的项目文件</li><li>B．CCB通过对变更方案的审查决策，对变更进行管理实施和控制</li><li>C．组织的结构文化管理实践和可持续性是影响指导与管理项目工作过程的因素</li><li>D．项目管理计划的任何组件都可用作指导与管理项目工作的输入</li></ul><details class="quiz" data-q="87" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B不正确。CCB是决策机构，不负责具体的管理实施和控制批准的变更请求是实施整体变更控制过程的输出，包括经项目经理审查和批准的变更请求，必要时需要经变更控制委员会(CCB)审查和批准（P252）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q88" class="quiz-anchor"></a></p><p><strong>88.</strong> 项目整合管理过程中，“实施已批准的变更”在（ ）过程中开展。</p><ul><li>A．实施整体变更控制</li><li>B．指导与管理项目工作</li><li>C．管理项目知识</li><li>D．监控项目工作</li></ul><details class="quiz" data-q="88" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：看清楚题且，他说的是“实施已批准的变更”在（ ）过程中开展，其实说的是已批准的变更是（ ）过程的输入（P251）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q89" class="quiz-anchor"></a></p><p><strong>89.</strong> （ ）不是管理项目知识过程的输出。在项目整合管理过程中，</p><ul><li>A．经验教训登记册</li><li>B．项目管理计划</li><li>C．组织过程资产</li><li>D．问题日志</li></ul><details class="quiz" data-q="89" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：问题日志是指导与管理项目工作的输出。管理项目知识过程的输出包括：1.经验教训登记册；2.项目管理计划（更新）;3.组织过程资产（更新）（P254）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q90" class="quiz-anchor"></a></p><p><strong>90.</strong> 关于指导与管理项目工作的描述，不正确的是（ ）。</p><ul><li>A．本过程执行项目管理计划中所确定的工作以实现项目目标</li><li>B．本过程的主要作用是对项目工作和可交付成果开展综合管理</li><li>C．变更请求在指导与管理项目工作过程中产生、批准并处理</li><li>D．项目管理计划的任何组件都可用作指导与管理项目工作的输入</li></ul><details class="quiz" data-q="90" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：指导与管理项目工作是为实现项目目标而领导和执行项目管理计划中所确定的工作，并实施已批准变更的过程。本过程的主要作用是对项目工作和可交付成果开展综合管理，以提高项目成功的可能性（P251）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q91" class="quiz-anchor"></a></p><p><strong>91.</strong> 问题日志文件在（ ）过程中被首次创建，随着项目进展在整个生命周期随时都需要对其进行监控。</p><ul><li>A．监控项目工作</li><li>B．指导与管理项目工作</li><li>C．管理项目知识</li><li>D．实施整体变更控制</li></ul><details class="quiz" data-q="91" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：问题日志可以帮助项目经理有效跟进和管理问题，确保它们得到调查和解决。作为指导与管理项目工作的输出，问题且志被首次创建，尽管在项目期间任何时候都可能发生问题（P254）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q92" class="quiz-anchor"></a></p><p><strong>92.</strong> 变更管理时，为了修正不一致产品或产品组件而进行的有目的活动被称为（ ）。</p><ul><li>A．缺陷补救</li><li>B．预防措施</li><li>C．问题日志</li><li>D．改进措施</li></ul><details class="quiz" data-q="92" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：变更请求一般包括：纠正措施：为使项目工作绩效重新与项目管理计划一致，而进行的有目的活动预防措施：为确保项目工作未来绩效符合项目管理计划，而进行的有目的活动（P254）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q93" class="quiz-anchor"></a></p><p><strong>93.</strong> 经验教训登记册通常在（ ）时创建，可以包含情况的类别和描述，还可包括与情况相关的影响建议和行动方案。</p><ul><li>A．项目测试</li><li>B．项目验收</li><li>C．项目开始</li><li>D．项目结束</li></ul><details class="quiz" data-q="93" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：经验教训登记册在项目早期创建，作为管理项目知识过程的输出。因此，在整个项目期间，它可以作为很多过程的输入，也可以作为输出而不断更新（P257）　<span class="quiz-src">教材第 8 章章节习题</span></p></details><p><a id="q94" class="quiz-anchor"></a></p><p><strong>94.</strong> 利用已有的组织知识来创造或改进项目成果，是（ ）过程的作用</p><ul><li>A．管理项目知识</li><li>B．指导与管理项目工作</li><li>C．监控项目工作</li><li>D．结束项目或阶段</li></ul><details class="quiz" data-q="94" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：管理项目知识是使用现有知识并生成新知识，以实现项目目标并且帮助组织学习的过程（P255）　<span class="quiz-src">自编</span></p></details><p><a id="q95" class="quiz-anchor"></a></p><p><strong>95.</strong> 管理项目知识的输入包括多种项目文件，其中（ ）说明项目已经具有的能力和经验以及可能缺乏的知识，（ ）包含有关团队组成的信息，有助于了解团队拥有的和缺乏的知识。</p><ul><li>A．项目团队派工单、资源分解结构</li><li>B．资源分解结构、项目团队派工单</li><li>C．干系人登记册、供方选择标准</li><li>D．供方选择标准、干系人登记册</li></ul><details class="quiz" data-q="95" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：管理项目知识的核心输入包括多种项目文件，其中项目团队派工单说明项目已经具有的能力和经验以及可能然乏的知识；资源分解结构包含有关团队组成的信息，有助于了解团队拥有的和缺乏的知识；干系人登记册包含已识别的干系人的详细情况，有助于了解他们可能拥有的知识；供方选择标准包含选择供方的标准，有助于了解供方拥有的知识（P255）　<span class="quiz-src">自编</span></p></details><p><a id="q96" class="quiz-anchor"></a></p><p><strong>96.</strong> 知识管理工具和技术包括（ ）。①人际交往；②实践社区和特别兴题小组；③讨论论坛；④讲故事；⑤编撰显性知识的方法6图书馆服务</p><ul><li>A．①②③④⑥</li><li>B．G④⑥</li><li>C．①2G④</li><li>D．℃④⑥</li></ul><details class="quiz" data-q="96" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：知识管理工具和技术主要包括：①人际交往；②实践社区和特别兴融小组；③会议；④工作跟随和跟随指导；⑥讨论论坛；⑥知识分室活动：⑦研讨公；③讲故事；④创造力和创意管理技术；⑩知识展公和茶座；交互式培训等（P256-257）　<span class="quiz-src">自编</span></p></details><p><a id="q97" class="quiz-anchor"></a></p><p><strong>97.</strong> 属于管理项目知识的成果是（ ）。①变更请求；②项目管理计划更新；③工作绩效信息；④工作绩效报告；⑤经验教训登记册⑥组织过程资产更新</p><ul><li>A．①②③</li><li>B．④⑤⑥</li><li>C．②③⑥</li><li>D．②⑤6</li></ul><details class="quiz" data-q="97" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理项目知识输出：1经验教训登记册；2.项目管理计划（更新）;3组组过程资产（更新）（P257）　<span class="quiz-src">自编</span></p></details><p><a id="q98" class="quiz-anchor"></a></p><p><strong>98.</strong> 关于经验教训登记册，不正确的是（ ）。</p><ul><li>A．经验教训登记册可以记录遇到的挑战、问题、意识到的风险和机会以及其他适用的内容</li><li>B．项目或阶段结束时，把相关信息归入经验教训知识库，作为组织过程资产一部分</li><li>C．经验教训登记册在项目早期创建，在整个项目期间不再更新</li><li>D．经验教训登记册可以包含执行情况的类别和详细的描述，还可包括与执行情况相关的影响、建议和行动方案</li></ul><details class="quiz" data-q="98" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：经验教训登记册在项目早期创建，作为管理项目知识过程的输出。因此，在整个项目期间，它可以作为很多过程的输入，也可以作为输出而不断更新（P257）　<span class="quiz-src">自编</span></p></details><p><a id="q99" class="quiz-anchor"></a></p><p><strong>99.</strong> 关于管理项目知识，不正确的是（ ）。</p><ul><li>A．管理项目知识是使用现有知识并生成新知识，以实现项目目标并且帮助组织学习的过程</li><li>B．知识管理最重要的环节就是营造一种相互信任的氛围，激励人们分享知识或关注他人的知识</li><li>C．可以联合使用知识管理工具和技术（用于人际互动）以及信息管理工具和技术（用于编撰显性知识）来分享知识</li><li>D．虚拟团队方式最有利于建立知识管理所需的信任关系</li></ul><details class="quiz" data-q="99" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：面对面互动最有利于建立知识管理所需的信任关系。信任关系建立后可以用虚拟互动来维护这种信任关系（P257）　<span class="quiz-src">自编</span></p></details><p><a id="q100" class="quiz-anchor"></a></p><p><strong>100.</strong> 管理项目知识中的人际关系与团队技能不包括（ ）。</p><ul><li>A．积极倾听</li><li>B．领导力</li><li>C．大局观</li><li>D．多标准决策</li></ul><details class="quiz" data-q="100" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理项目知识中的人际关系与团队技能包括：积极倾听；引导；领导力；人际交往；大局观（P257）　<span class="quiz-src">自编</span></p></details><p><a id="q101" class="quiz-anchor"></a></p><p><strong>101.</strong> 关于项目知识管理的描述，正确的是（ ）。</p><ul><li>A．先进的虚拟互动技术最有利于建立知识管理所需的信任关系</li><li>B．信息管理工具和技术用于创建人们与知识之间的联系，有利于隐性知识的传插</li><li>C．信任关系建立后可以用虚拟互动来维护这种信任关系</li><li>D．工作绩效信息属于管理项目知识的成果</li></ul><details class="quiz" data-q="101" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：面对面互动最有利于建立知识管理所需的信任关系。信任关系建立后可以用虚拟互动来维护这种信任关系；信息管理工具和技术用于创建人们与知识之间的联系，可以有效促进简单、明确的显性知识的分室，主要包括：①编撰显性知识的方法；②经验教训登记册；③图书馆服务；④信息收集⑤项目管理信息系统等（P257）　<span class="quiz-src">自编</span></p></details><p><a id="q102" class="quiz-anchor"></a></p><p><strong>102.</strong> 以下说法不正确的是（ ）。</p><ul><li>A．管理项目知识需要在整个项目期间开展</li><li>B．知识管理工具和技术将员工高洋联系起来，使他们能够合作生成新知识，分享隐性知识，以及集成不同团队成员所拥有的知识</li><li>C．知识管理最重要的环节就是营造一种相互信任的氛围，激励人们分享知识或关注他人的知识</li><li>D．信息管理工具和技术用于创建人们与知识之间的联系，有利于隐性知识的传播</li></ul><details class="quiz" data-q="102" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：信息管理工具和技术用于创建人们与知识之间的联系，可以有效促进简单、明确的显性知识的分享，主要包括：①编制显性知识的方法；②经验教训登记册；③图书馆服务；④信息收集⑤项目管理信息系统等，（P257）　<span class="quiz-src">自编</span></p></details><p><a id="q103" class="quiz-anchor"></a></p><p><strong>103.</strong> （ ）在项目早期创建，作为管理项目知识过程的输出，既可以作为很多过程的输入，也可以作为输出而不断更新。</p><ul><li>A．项目章程</li><li>B．经验教训登记册</li><li>C．问题日志</li><li>D．干系人登记册</li></ul><details class="quiz" data-q="103" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：经验教训登记册在项目早期创建，作为管理项目知识过程的输出。因此，在整个项目期间它可以作为很多过程的输入，也可以作为输出而不断更新（P257）　<span class="quiz-src">自编</span></p></details><p><a id="q104" class="quiz-anchor"></a></p><p><strong>104.</strong> 经验教训登记册记录（ ）。</p><ul><li>A．项目的具体预算、合同价格</li><li>B．问题日志中的问题及问题解决所采取的措施</li><li>C．源代码系统架构的详细设计</li><li>D．项目内部的决策过程、会议记录、讨论记录</li></ul><details class="quiz" data-q="104" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：经验教训登记册可以包含情况的类别和描述，还可以包括与情况相关的影响、建议和行动方案。经验教训登记册可以记录遇到的挑成、问题、意识到的风险和机会，或其他适用的内容（P257）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q105" class="quiz-anchor"></a></p><p><strong>105.</strong> 管理项目知识过程的日的是（ ）。</p><ul><li>A．确保文档妥善保存</li><li>B．编制项目总结报告</li><li>C．利用知识实现项目目标</li><li>D．对成员进行培训</li></ul><details class="quiz" data-q="105" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：255。管理项目知识是使用现有知识并生成新知识，以实现项目目标，并且董助组组学习的过程。本过程的主要作用是，利用已有的组织知识来创造或改进项目成果，并且使当前项目创造的知识可用于支持组织运营和未来的项目或阶段　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q106" class="quiz-anchor"></a></p><p><strong>106.</strong> 关于项目知识管理的描述，不正确的是（ ）。</p><ul><li>A．项目管理计划的所有组成部分都是管理项目知识过程的输入</li><li>B．知识管理最重要的环节是营造相互信任的氛围</li><li>C．知识管理需在整个项目期间开展</li><li>D．先进的虚拟互动技术最有利于建立知识管理所需的信任关系</li></ul><details class="quiz" data-q="106" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：可以通过面对面和虚拟方式来应用所有这些工具和技术。通常，面对面互动最有利于建立知识管理所需的信任关系。信任关系建立后可以用虚拟互动来维护这种信任关系（P257）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q107" class="quiz-anchor"></a></p><p><strong>107.</strong> 关于管理项目知识过程的描述，正确的是（ ）。</p><ul><li>A．项目管理计划的所有组成部分都是管理项目知识的输入</li><li>B．选取先进的知识管理工具是知识管理最重要的环节</li><li>C．项目管理知识应该有明确的范围，确保知识只为本项目服务</li><li>D．专家判断不属于项目知识管理的工具与技术</li></ul><details class="quiz" data-q="107" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A正确。项目管理计划的所有组成部分都是管理项目知识的输入。B不正确。知识管理最重要的环节就是营造一种相互信任的氛围。C不正确（P255）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q108" class="quiz-anchor"></a></p><p><strong>108.</strong> 在管理项目知识时，（ ）可促进项目干系人之间建立非正式的联系和关系</p><ul><li>A．领导力</li><li>B．积极倾听</li><li>C．人际交往</li><li>D．大局观</li></ul><details class="quiz" data-q="108" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：可用于管理项目知识过程的人际关系与团队技能主要包括·积极倾听：有助于减少误解并促进沟通和知识分享。·引导：有助于有效指引团队成功地达成决定、解决方案或结论（P257）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q109" class="quiz-anchor"></a></p><p><strong>109.</strong> 监控项目工作过程的主要作用是（ ）。</p><ul><li>A．生成一份综合文件，用于确定所有项目工作的基础及其执行方式</li><li>B．对项目工作和可交付成果开展综合管理，以提高项目成功的可能性</li><li>C．让干系人了解项目的当前状态并认可为处理绩效问题而采取的行动，以及通过成本和进度预测，让干系人了解未来项目状态</li><li>D．利用已有的组织知识来创造或改进项目成果，并且使当前项目创造的知识可用于支持组织运营和未来的项目或阶段</li></ul><details class="quiz" data-q="109" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：监控项目工作是跟踪、审查和报告整体项目进展，以实现项目管理计划中确定的绩效目标的过程。本过程的主要作用：①让干系人了解项目的当前状态并认可为处理绩效问题而采取的行动；②通过成本和进度预测，让干系人了解项目的未来状态（P258）　<span class="quiz-src">教材第 8 章章节习题</span></p></details><p><a id="q110" class="quiz-anchor"></a></p><p><strong>110.</strong> 监控项目工作过程中的控制，不包括（ ）。</p><ul><li>A．制定纠正或预防措施或重新规划</li><li>B．预测趋势，以便推动过程改进</li><li>C．重新规划</li><li>D．跟踪行动计划的实施过程，以确保它们能有效解决问题</li></ul><details class="quiz" data-q="110" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B不正确，预测趋势属于监督过程监督是贯穿于整个项目的项目管理活动之一，包括收集、测量和分析测量结果，以及预测趋势，以便推动过程改进（P258）　<span class="quiz-src">教材第 8 章章节习题</span></p></details><p><a id="q111" class="quiz-anchor"></a></p><p><strong>111.</strong> 监控项目工作过程中的监督，不包括（ ）。</p><ul><li>A．收集信息</li><li>B．分析测量结果</li><li>C．预测趋势</li><li>D．制定纠正</li></ul><details class="quiz" data-q="111" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：监督是贯穿于整个项目的项目管理活动之一，包括收集、测量和分析测量结果，以及预测趋势，以便推动过程改进（P258）　<span class="quiz-src">自编</span></p></details><p><a id="q112" class="quiz-anchor"></a></p><p><strong>112.</strong> （ ）过程将工作绩效信息作为输入。</p><ul><li>A．监控项目工作</li><li>B．确认范围</li><li>C．控制范围</li><li>D．控制进度</li></ul><details class="quiz" data-q="112" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：监控项目工作过程的主要输入为：1项目管理计划，2项目文件，3工作绩效信息，4协议，“5.事业环境因素，6.组织过程资产（P259）　<span class="quiz-src">自编</span></p></details><p><a id="q113" class="quiz-anchor"></a></p><p><strong>113.</strong> 用于在出现偏差时选择要执行的纠正措施或纠正措施和预防措施的组合，属于（ ）</p><ul><li>A．备选方案分析</li><li>B．偏差分析</li><li>C．趋势分析</li><li>D．决策</li></ul><details class="quiz" data-q="113" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O。备选方案分析：用于在出现偏差时选择要执行的纠正措施或纠正措施和预防措施的组合（P26）　<span class="quiz-src">自编</span></p></details><p><a id="q114" class="quiz-anchor"></a></p><p><strong>114.</strong> （ ）关注识别问题的主要原因，它可用于识别出现偏差的原因以及项目经理为达成项目目标应重点关注的领域。</p><ul><li>A．成本效益分析</li><li>B．根本原因分析</li><li>C．趋势分析</li><li>D．偏差分析</li></ul><details class="quiz" data-q="114" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O。根本原因分析：关注识别问题的主要原因，它可用于识别出现偏差的原因以及项目经理为达成项目目标应重点关注的领域（P26）　<span class="quiz-src">自编</span></p></details><p><a id="q115" class="quiz-anchor"></a></p><p><strong>115.</strong> 投票常用的决策方法不包括（ ）。</p><ul><li>A．一致同意</li><li>B．大多数同意</li><li>C．相对多数原则</li><li>D．独裁</li></ul><details class="quiz" data-q="115" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：260-261。投票可以包括用下列方法进行决策；二致同意、大多数同意或相对多数原则。独裁虽然属于决策技术的一种，但不属于投票决策的方法　<span class="quiz-src">自编</span></p></details><p><a id="q116" class="quiz-anchor"></a></p><p><strong>116.</strong> 不属于工作绩效报告的是（ ）。</p><ul><li>A．挣值图表和信息</li><li>B．趋势线和预测</li><li>C．缺陷直方图</li><li>D．技术绩效测量结果</li></ul><details class="quiz" data-q="116" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：技术绩效测量结果是工作绩效数据。工作绩效报告的内容一般包括状态报告和进展报告。工作绩效报告可以包含挣值图表和信息趋势线和预测、储备燃尽图、缺陷直方图、合同绩效信息和风险情况概述（P261）　<span class="quiz-src">自编</span></p></details><p><a id="q117" class="quiz-anchor"></a></p><p><strong>117.</strong> （ ）不属于项目监控的工作内容。</p><ul><li>A．随时收集干系人需求</li><li>B．分析项目风险</li><li>C．测量项目绩效</li><li>D．分发绩效信息</li></ul><details class="quiz" data-q="117" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「随时收集干系人需求」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q118" class="quiz-anchor"></a></p><p><strong>118.</strong> （ ）可用于识别出现偏差的原因以及项目经理为达成项目目标应重点关注的领域。</p><ul><li>A．偏差分析</li><li>B．趋势分析</li><li>C．根本原因分析</li><li>D．挣值分析</li></ul><details class="quiz" data-q="118" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：260，根本原因分析：关注识别问题的主要原因。它可用于识别出现偏差的原因以及项目经理为达成项目目标应重点关注的领域　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q119" class="quiz-anchor"></a></p><p><strong>119.</strong> 关于监控项目工作的描述，正确的是（ ）。</p><ul><li>A．监控项目工作输出工作绩效数据</li><li>B．监控项目工作输出风险登记册</li><li>C．监控项目工作输入工作绩效报告</li><li>D．监控项目工作只在项目执行阶段开展</li></ul><details class="quiz" data-q="119" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：监控项目工作过程需要在整个项目期间开展。输入：①项目管理计划；②项目文件（假设日志、风险登记册、风险报告、里程砷清单、估算依据、问题日志、经验教训登记册、成本预测、进度预测、质量报告）;③工作绩效信息；④协议；⑤事业环境因素；⑥组织过程资产（P258-261）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q120" class="quiz-anchor"></a></p><p><strong>120.</strong> 项目经理向公司管理层汇报项目进展情况时最适合采用（ ）。</p><ul><li>A．工作绩效数据</li><li>B．工作绩效信息</li><li>C．工作绩效报告</li><li>D．项目管理计划</li></ul><details class="quiz" data-q="120" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「工作绩效报告」，原解析未给课本依据　<span class="quiz-src">2019 年下半年高项</span></p></details><p><a id="q121" class="quiz-anchor"></a></p><p><strong>121.</strong> 监控项目工作的输出不包括（ ）。</p><ul><li>A．变更请求</li><li>B．工作绩效信息</li><li>C．项目管理计划更新</li><li>D．项目文件更新</li></ul><details class="quiz" data-q="121" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B错误。工作绩效信息是监控项目工作的输入。项目监控工作输出有：1变更请求、2.工作绩效报告、3项目管理计划更新、4.项目文件更缸（P261）　<span class="quiz-src">2019 年上半年高项</span></p></details><p><a id="q122" class="quiz-anchor"></a></p><p><strong>122.</strong> （ ）不属于“监控项目工作”过程使用的工具和技术。</p><ul><li>A．专家判断</li><li>B．分析技术</li><li>C．访问控制</li><li>D．会议</li></ul><details class="quiz" data-q="122" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：C错误。监控项目工作属于整合管理的过程之一，其工具与技术包括：专家判断、数据分析技术、决策、会议（P260-261）　<span class="quiz-src">2020 年下半年高项</span></p></details><p><a id="q123" class="quiz-anchor"></a></p><p><strong>123.</strong> 监控项目工作过程包括了监视和控制两方面的活动，（ ）属于控制活动。</p><ul><li>A．采取预防措施</li><li>B．收集绩效信息</li><li>C．测量绩效信息</li><li>D．评价测量结果</li></ul><details class="quiz" data-q="123" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：监视是贯穿项目始终的项目管理的一个方面。监视包括收集、测量并散发绩效信息，并评价测量结果和实施过程改进的趋势。连续的监视使项目管理团队能够洞察项目的状态是否正常，并识别任何可能要求给予特别注意的方面（P258）　<span class="quiz-src">2022 年下半年高项</span></p></details><p><a id="q124" class="quiz-anchor"></a></p><p><strong>124.</strong> 监控项目工作过程中，出现偏差时，需使用（ ）在多个方案中选择要执行的纠正措施和预防措施；需使用（ ）技术确定最节约成本的纠正措施；需使用（ ）技术对范围、进度和成本绩效进行综合分析。</p><ul><li>A．偏差分析、备选方案分析、成本效益分析</li><li>B．备选方案分析、成本效益分析、挣值分析</li><li>C．备选方案分析、偏差分析、成本效益分析</li><li>D．偏差分析、备选方案分析、挣值分析</li></ul><details class="quiz" data-q="124" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O。可用于监控项目工作过程的数据分析技术主要包括：◆备选方案分析：用于在出现偏差时选择要执行的纠正措施或纠正措施和预防措施的组合◆成本效益分析：有助于出现偏差时确定最节约成本的纠正措施挣值分析：对范围、进度和成本绩效进行了综合分析（P26）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q125" class="quiz-anchor"></a></p><p><strong>125.</strong> 监督是贯穿于整个项目的项目管理活动之一，包括收集、测量和（ ），以及预测趋势，以便推动（ ）。</p><ul><li>A．分析收集数据、数据分析</li><li>B．分析测量结果、过程改进</li><li>C．评估项目绩效、绩效优化</li><li>D．检查项目风险、风险管理</li></ul><details class="quiz" data-q="125" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：监督是贯穿于整个项目的项目管理活动之一，包括收集、测量和分析测量结果，以及预测趋势，以便推动过程改进（P258）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q126" class="quiz-anchor"></a></p><p><strong>126.</strong> 关于实施整体变更控制过程，不正确的是（ ）。</p><ul><li>A．在基准确定之前，变更无须正式受控于实施整体变更控制过程</li><li>B．变更请求可能影响项目范围、产品范围以及任一项目管理计划组件或任一项目文件</li><li>C．在整个项目生命周期的任何时间，并不是所有参与项目的干系人都可以提出变更请求</li><li>D．尽管也可以口头提出，但所有变更请求都必须以书面形式记录，并纳入变更管理和配置管理系统中</li></ul><details class="quiz" data-q="126" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：实施整体变更控制过程贯穿项目始终，项目经理对此承担最终责任。变更请求可能影响项目范围、产品范围以及任一项目管理计划组件或任一项目文件（P262）　<span class="quiz-src">教材第 8 章章节习题</span></p></details><p><a id="q127" class="quiz-anchor"></a></p><p><strong>127.</strong> （ ）是指审查所有变更请求，批准变更，管理对可交付成果、组织过程资产、项目文件和项目管理计划的变更，并对变更处理结果进行沟通的过程。</p><ul><li>A．监控项目工作</li><li>B．指导与管理项目工作</li><li>C．管理沟通</li><li>D．实施整体变更控制</li></ul><details class="quiz" data-q="127" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：实施整体变更控制是指审查所有变更请求，批准变更，管理对可交付成果、组织过程资产、项目文件和项目管理计划的变更，并对变更处理结果进行沟通的过程（P262）　<span class="quiz-src">自编</span></p></details><p><a id="q128" class="quiz-anchor"></a></p><p><strong>128.</strong> （ ）的主要作用是，确保对项目中已记录在案的变更做综合评审。</p><ul><li>A．实施整体变更控制</li><li>B．变更管理</li><li>C．监控项目工作</li><li>D．指导与管理项目工作</li></ul><details class="quiz" data-q="128" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：262。实施整体变更控制的主要作用是，确保对项目中已记录在案的变更做综合评审　<span class="quiz-src">自编</span></p></details><p><a id="q129" class="quiz-anchor"></a></p><p><strong>129.</strong> 关于项目整体变更控制的描述，正确的是（ ）。</p><ul><li>A．项目整体变更控制过程只用于项目的执行和监控阶段</li><li>B．只有客户或项目管理人员才能提出变更请求</li><li>C．每项记录在案的变更请求都必须由一位责任人批准或否决</li><li>D．CCB对变更请求的审批结果不可更改</li></ul><details class="quiz" data-q="129" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：每项记录在案的变更请求都必须由一位责任人批准或否决，这个责任人通常是项目发起人或班且经理（P262）　<span class="quiz-src">自编</span></p></details><p><a id="q130" class="quiz-anchor"></a></p><p><strong>130.</strong> 关于整体变更控制的描述，不正确的是（ ）。</p><ul><li>A．项目的任何干系人都可以提出变更请求</li><li>B．项目经理可以是变更控制委员会CCB的成员</li><li>C．整体变更控制过程贯穿项目始终，CCB对此负最终责任</li><li>D．整体变更控制的主要作用是降低因未考虑变更对整个项目计划的影响而产生的风险</li></ul><details class="quiz" data-q="130" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：整体变更控制过程贯穿项目始终，项目经理对此负最终责任（P262）　<span class="quiz-src">自编</span></p></details><p><a id="q131" class="quiz-anchor"></a></p><p><strong>131.</strong> 关于实施项目整体变更控制过程的描述，不正确的是（ ）。</p><ul><li>A．尽管可以口头提出，但所有变更请求都必须以书面形式记录</li><li>B．在基准确定之前，变更也应正式受控，实施整体变更控制过程</li><li>C．实施整体变更控制过程贯穿项目始终，项目经理对此承担最终责任</li><li>D．项目的任何干系人都可以提出变更请求</li></ul><details class="quiz" data-q="131" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：在基准确定之前，变更无须正式受控并实施整体变更控制过程。一且确定了项目基淮，就必须通过实施整体变更控制过程来处理变更请求（P262）　<span class="quiz-src">自编</span></p></details><p><a id="q132" class="quiz-anchor"></a></p><p><strong>132.</strong> 以下关于项目变更管理的叙述中，不正确的是（ ）。</p><ul><li>A．项目的任何干系人都可以提出变更请求</li><li>B．所有的变更请求都必须以书面形式记录</li><li>C．所有的变更请求都必须交由变更控制委员会审批</li><li>D．客户也可以作为变更控制委员会成员</li></ul><details class="quiz" data-q="132" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：变更可能影响项目基淮，也可能不影响项目基准，变更决定通常由项目经理做决策。对于会影响项目基准的变更，通常应该在变更请求中说明执行变更的成本、所需的计划日期修改、资源蛋求以及相关的风险（P263）　<span class="quiz-src">自编</span></p></details><p><a id="q133" class="quiz-anchor"></a></p><p><strong>133.</strong> 实施整体变更控制需要根据（ ）中的纠正措施、预防措施、缺陷补救来进行，其中影响项目基准的变更，应由（ ）和客户或发起人审批，只有经批准的变更才能纳入修改后的基准。</p><ul><li>A．变更请求、CCB</li><li>B．批准的变更请求、项目经理</li><li>C．项目管理计划、CCB</li><li>D．配置项、客户</li></ul><details class="quiz" data-q="133" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目执行中很多过程都会输出变更请求。变更请求可能包含纠正措施、预防措施、缺陷补救，以及针对正式受控的项目文件或可交付成果的更新（P263）　<span class="quiz-src">自编</span></p></details><p><a id="q134" class="quiz-anchor"></a></p><p><strong>134.</strong> 变更控制工具需要支持的配置管理活动不包括（ ）。</p><ul><li>A．识别配置项</li><li>B．记录并报告配置项状态</li><li>C．进行配置项核实与审计</li><li>D．配置项控制</li></ul><details class="quiz" data-q="134" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：变更控制工具需要支持的配置管理活动包括：今迟别配置项：识别与选择配置项，为定义与核实产品配置、标记产品和文件、管理变更和明确责任提供基础（P264）　<span class="quiz-src">自编</span></p></details><p><a id="q135" class="quiz-anchor"></a></p><p><strong>135.</strong> 配置管理和变更管理是项目管理中非常重要的组成部分，两者相比，配置管理重点关注（ ）</p><ul><li>A．项目可交付成果及各个过程技术之间的匹配</li><li>B．识别、记录对项目文件的更改</li><li>C．批准或否决对项目文件的改变</li><li>D．对项目可交付成果或基准变更的记录</li></ul><details class="quiz" data-q="135" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：配置控制重点关注可交付成果及各个过程的技术规范之间的匹配问题，而变更控制则着眼于识别、记录、批准或否决对项目文件、可交付成果或基准的变更（P264）　<span class="quiz-src">自编</span></p></details><p><a id="q136" class="quiz-anchor"></a></p><p><strong>136.</strong> （ ）不属于变更管理中涉及的配置管理活动。</p><ul><li>A．识别配置项</li><li>B．记录并报告配置项状态</li><li>C．进行配置项核实与审计</li><li>D．版本管理</li></ul><details class="quiz" data-q="136" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：变更管理中涉及的配置管理活动包括：迟别配置项、记录并报告配置项状态、进行配置项核实与审让（P264）　<span class="quiz-src">自编</span></p></details><p><a id="q137" class="quiz-anchor"></a></p><p><strong>137.</strong> 变更控制工具还需要支持的变更管理活动不包括（ ）。</p><ul><li>A．识别变更</li><li>B．做出变更决定</li><li>C．跟踪变更</li><li>D．结束变更</li></ul><details class="quiz" data-q="137" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：变更控制工具还需要支持的变更管理活动包括：◆识别变更：识别并选择过程或项目文件的变更项；记录变更：将变更记录为合适的变更请求；◆做出变更决定：审查变更，批准、否决、推迟对项目文件、可交付成果或基准的变更或做出其他决定；跟踪变更：确认变更被登记、评估、批准和跟踪，并向干系人传达最终结果；（P264）　<span class="quiz-src">自编</span></p></details><p><a id="q138" class="quiz-anchor"></a></p><p><strong>138.</strong> 关于配置控制和变更控制的理解，不正确的是（ ）。</p><ul><li>A．配置控制重点关注可交付成果及各个过程的技术规范</li><li>B．变更控制则重点关注识别、记录、批准或否决对项目文件、可交付成果或基准的变更</li><li>C．通过配置核实与审计，确保项目的配置项组成的正确性</li><li>D．变更管理活动需要变更控制工具的支持，配置管理活动不需要</li></ul><details class="quiz" data-q="138" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：配置管理活动和变更管理活动都需要变更控制工具的支持（P264）　<span class="quiz-src">自编</span></p></details><p><a id="q139" class="quiz-anchor"></a></p><p><strong>139.</strong> 整体变更控制的工具与技术不包括（ ）。</p><ul><li>A．专家判断</li><li>B．知识管理</li><li>C．备选方案分析</li><li>D．决策</li></ul><details class="quiz" data-q="139" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：实施整体变更控制的工具与技术：1专家判断；2.变更控制工具；3.数据分析（备选方案分析、成本效益分析）;4.决策（投票、独裁型决策制定、多标准决策分析）;5会议知识管理是管理项目知识的工具，（P264-265）　<span class="quiz-src">自编</span></p></details><p><a id="q140" class="quiz-anchor"></a></p><p><strong>140.</strong> 以下关于整体变更控制的叙述中，不正确的是（ ）。</p><ul><li>A．一个未知风险发生影响到项目进度时，需要进行整体变更分析</li><li>B．未经批准的变更请求不需要在变更日志中记录</li><li>C．变更请求可以口头提出，但要以书面形式记录</li><li>D．变更请求在CCB批准后，还可能需要得到客户或发起人的批准</li></ul><details class="quiz" data-q="140" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正式受控的任一项目文件都可在实施整体变更控制过程变更，同时并将项目期间发生的变更全部记录在变更日志中（P265）　<span class="quiz-src">自编</span></p></details><p><a id="q141" class="quiz-anchor"></a></p><p><strong>141.</strong> 关于实施整体变更控制的相关描述，不正确的是（ ）。</p><ul><li>A．实施整体变更控制的作用是确保对项目中已记录在案的变更做出综合评审</li><li>B．在整个项目生命周期的任何时间，参与项目的任何干系人都可以提出变更请求</li><li>C．对基准的变更可基于历史版本的基准，也可变更以往的绩效数据</li><li>D．每项记录在案的变更请求都必须由一位责任人批准、推迟或否决</li></ul><details class="quiz" data-q="141" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「对基准的变更可基于历史版本的基准，也可变更以往的绩效数据」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q142" class="quiz-anchor"></a></p><p><strong>142.</strong> 在项目执行的过程中，一名干系人确定了一个新需求，该需求对项目是否成功起到关键的作用，项目经理接下来应该（ ）。</p><ul><li>A．为该需求建立变更请求，提交给变更控制委员会审批</li><li>B．评估重要性，以确定是否执行变更流程</li><li>C．寻求项目发起人对变更的批准</li><li>D．考虑该需求比较关键，安排相关人员进行修改</li></ul><details class="quiz" data-q="142" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「为该需求建立变更请求，提交给变更控制委员会审批」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q143" class="quiz-anchor"></a></p><p><strong>143.</strong> 关于变更申请的描述，不正确的是（ ）。</p><ul><li>A．实施整体变更控制过程贯穿项目始终</li><li>B．变更请求可能包括纠正措施、预防措施和缺陷补救</li><li>C．变更请求必须由CCB来负责审查、评价、批准或否决</li><li>D．实施整体变更过程中涉及的配置管理活动包括配置识别、配置状态记录、配置核实与审计</li></ul><details class="quiz" data-q="143" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：C错误。影响项目基准的变更才交由变更控制委员会审批变更可能影响项目基准，也可能不影响项目基准，变更决定通常由项目经理做决策（P263）　<span class="quiz-src">2018 年上半年高项</span></p></details><p><a id="q144" class="quiz-anchor"></a></p><p><strong>144.</strong> （ ）不属于整体变更控制的成果。</p><ul><li>A．批准的变更请求</li><li>B．工作绩效报告</li><li>C．变史日志</li><li>D．项目文件更新</li></ul><details class="quiz" data-q="144" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B错误。工作绩效报告是整体变更控制的输入。整体变更控制的成果包括：1.批准的变更请求、2.项目管理计划更新、3.项目文件更新（P265）　<span class="quiz-src">2020 年下半年高项</span></p></details><p><a id="q145" class="quiz-anchor"></a></p><p><strong>145.</strong> （ ）是整体变更控制的依据。①项目管理计划；②批准的变更请求；③验收的可交付成果；④配置管理系统；⑤组织过程资产</p><ul><li>A．①③④</li><li>B．①②④</li><li>C．②③⑤</li><li>D．①④⑤</li></ul><details class="quiz" data-q="145" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：①正确。所有的控制过程组的输入中都有项目管理计划。②错误。批准的变更请求是整体变更控制的输出。③错误。验收的可交付成果是结束项目或阶段的输入④正确（P263）　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q146" class="quiz-anchor"></a></p><p><strong>146.</strong> 属于整体变更控制成果的是（ ）①变更请求；②项目管理计划更新；③工作绩效信息；④工作绩效报告；⑤变更日志；⑥项目文件更新</p><ul><li>A．①②⑤</li><li>B．④⑤6</li><li>C．②③⑥</li><li>D．②⑤⑥</li></ul><details class="quiz" data-q="146" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：整体变更控制的成果包括：1.批准的变更请求、2.项目管理计划更新、3.项目文件更新（P265）　<span class="quiz-src">2021 年下半年高项</span></p></details><p><a id="q147" class="quiz-anchor"></a></p><p><strong>147.</strong> 某IT项目在实施整体变更控制过程中，（ ）必须记录在变更日志中。</p><ul><li>A．项目干系人提出但被否决的新功能请求</li><li>B．经CCB批准的需求范围的扩展</li><li>C．风险管理计划中的应对策略</li><li>D．纠正项目管理计划中的拼写错误</li></ul><details class="quiz" data-q="147" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：选项A错误：被否决的变更请求需要记录在变更日志中，但是本题的关键是，这个变更请求是否能到审批环节，如果未提交正式变更申请（仅口头提出），无需记录在变更日志中（P262）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q148" class="quiz-anchor"></a></p><p><strong>148.</strong> 实施整体变更控制”的输入不包括（ ）。</p><ul><li>A．批准的变更请求</li><li>B．进度基准</li><li>C．范围基准</li><li>D．工作绩效报告</li></ul><details class="quiz" data-q="148" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：批准的变更请求是实施整体变更控制过程的输出（P265）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q149" class="quiz-anchor"></a></p><p><strong>149.</strong> 以下哪一个说法是错误的（ ）。</p><ul><li>A．变更请求可能影响项目范围、产品范围以及任一项目管理计划组件或项目文件</li><li>B．所有变更请求都必须以书面形式记录，并纳入变更管理和配置管理系统中</li><li>C．变更请求得到批准后，可能需要修订成本估算、进度日期、资源需求和风险应对方案</li><li>D．整体变更控制流程中，需要安排AB角色负责</li></ul><details class="quiz" data-q="149" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：ABC都是课本原话，D不正确，每项记录在案的变更请求都必须由二位责任人批准、推迟或否决。这里的AB角色负责不符合独立责任原则（P262）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q150" class="quiz-anchor"></a></p><p><strong>150.</strong> 关于结束项目或阶段过程及相关描述，正确的是（ ）。“①结束项目或阶段是终结项目、阶段或合同的所有活动的过程②结束项目或阶段过程需要在整个项目期间反复开展，确保项目顺利推进③结束项目时，项目经理需回顾项目管理计划，确保所有项目工作完成、目标实现④若项目提前终止，可以直接关闭项目⑤该过程的作用包括存档项目信息、释放组织团队资源以展开新工作</p><ul><li>A．①③⑤</li><li>B．①②④</li><li>C．②③⑤</li><li>D．①③④</li></ul><details class="quiz" data-q="150" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：结束项目或阶段是终结项目、阶段或合同的所有活动的过程，其作用包括在档项目或阶段信品、完成计划的工作，以及释放组织团队资激以展开新的工作（P265-266）　<span class="quiz-src">自编</span></p></details><p><a id="q151" class="quiz-anchor"></a></p><p><strong>151.</strong> 结束项目或阶段过程所需执行的活动不包括（ ）。</p><ul><li>A．为达到阶段或项目的完工或退出标准所必须的行动和活动</li><li>B．为关闭项目合同协议或项目阶段合同协议所必须开展的活动</li><li>C．为向下一个阶段，或者向生产和（或）运营部门移交项目的产品、服务或成果所必须开展的行动和活动</li><li>D．如果项目在完工前提前终止，只要关键干系人都允许，客户付完尾款后就可以终止项目</li></ul><details class="quiz" data-q="151" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：如果项目在完工前提前终止，结束项目或阶段过程还需要制定程序，调查和记录提前终止的原因。为了实现上述目的，项目经理应该引导所有合适的干系人参与结束项目或阶段的工作（P266）　<span class="quiz-src">自编</span></p></details><p><a id="q152" class="quiz-anchor"></a></p><p><strong>152.</strong> （ ）不属于结束项目或阶段的输出。</p><ul><li>A．经验教训登记册</li><li>B．最终产品、服务或成果</li><li>C．项目最终报告</li><li>D．验收的可交付成果</li></ul><details class="quiz" data-q="152" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：结束项目或阶段的输出：1项目文件更新（经验教训登记册）;2.最终产品、服务或成果；3.项目最终报告；4.组织过程资产更新；验收的可交付成果是结束项目或阶段的输入（P266）　<span class="quiz-src">自编</span></p></details><p><a id="q153" class="quiz-anchor"></a></p><p><strong>153.</strong> 关于结束项目或阶段，不正确的是（ ）。</p><ul><li>A．如果项目在完工前提前终止，结束项目或阶段过程还需要制定程序，调查和记录提前终止的原因。为了实现上述目的，项目经理应该引导所有重要的干系人参与结束项目或阶段的工作</li><li>B．验收的可交付成果可包括批准的产品规范、交货收据和工作绩效文件。对于分阶段实施的项目或提前取消的项目，还可能包括部分完成或中间的可交付成果</li><li>C．结束项目或阶段是终结项目、阶段或合同的所有活动的过程。本过程的主要作用：①存档项目或阶段信息，完成计划的工作；②释放组织团队资源以展开新的工作</li><li>D．结束项目或阶段仅开展一次或仅在项目或阶段的结束点开展</li></ul><details class="quiz" data-q="153" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：如果项目在完工前提前终止，结束项目或阶段过程还需要制定程序，调查和记录提前终止的原因。为了实现上述目的，项目经理应该引导所有合适的干系人参与结束项目或阶段的工作（P266）　<span class="quiz-src">自编</span></p></details><p><a id="q154" class="quiz-anchor"></a></p><p><strong>154.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．验收的可交付成果可包括批准的产品规范、交货收据和工作绩效文件</li><li>B．在复杂项目中，可能需要同时或先后管理多个合同</li><li>C．为关闭合同，需收集全部采购文档，并建立索引、加以归档</li><li>D．如果项目在完工前就提前终止，那么就没有必要进行干系人满意度的调查</li></ul><details class="quiz" data-q="154" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：如果项目在完工前就提前终止，结束项目或阶段过程还需要制定程序，来调查和记录提前终止的原因（P266）　<span class="quiz-src">自编</span></p></details><p><a id="q155" class="quiz-anchor"></a></p><p><strong>155.</strong> （ ）用于分析项目结果的不同项目变量之间的相互关系，以提高未来项目的绩效。</p><ul><li>A．文件分析</li><li>B．回归分析</li><li>C．趋势分析</li><li>D．偏差分析</li></ul><details class="quiz" data-q="155" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：回归分析：该技术分析作用于项目结果的不同项目变量之间的相互关系，以提高未来项目的绩效（P268）　<span class="quiz-src">自编</span></p></details><p><a id="q156" class="quiz-anchor"></a></p><p><strong>156.</strong> 适用于结束项目或阶段的数据分析技术是（ ）。</p><ul><li>A．回归分析</li><li>B．根本原因分析</li><li>C．假设条件和制约因素分析</li><li>D．反馈</li></ul><details class="quiz" data-q="156" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：可用于结束项目或阶段的数据分析技术主要包括：文性分析：评估现有文件有助于总结经验教训和分享知识，以改进未来项目和组织资产今回归分析：该技术分析作用于项目结果的不同项目变量之间的相互关系，以提高未来项目的绩效（P268）　<span class="quiz-src">自编</span></p></details><p><a id="q157" class="quiz-anchor"></a></p><p><strong>157.</strong> 关于结束项目或阶段过程的相关描述，正确的是（ ）。</p><ul><li>A．其输入包括最终产品、服务或成果</li><li>B．主要作用包括存档项目信息、释放组织团队资源</li><li>C．经验教训知识库是它的工作依据</li><li>D．分析资源投入与项目质量的关联性最适用于趋势分析</li></ul><details class="quiz" data-q="157" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：A不正确。最终产品、服务或成果是结束项目或阶段过程的输出，并非输入。B正确。结束项目或阶段的作用包括：在档项目成阶段信息，完成计划的工作；释放组织团队资源以展开新的工作（P265-269）　<span class="quiz-src">自编</span></p></details><p><a id="q158" class="quiz-anchor"></a></p><p><strong>158.</strong> 在项目整合管理过程中（ ）不属于“结束项目或阶段”过程的输入。</p><ul><li>A．项目章程</li><li>B．项目最终报告</li><li>C．项目管理计划</li><li>D．验收的可交付成果</li></ul><details class="quiz" data-q="158" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目最终报告是“结束项目或阶段”过程的输出。结束项目或阶段的输入：1项目章程；2.项目管理计划；3.项目文件；4.验收的可交付成果：5.立项管理文件；6.协议；7，采购文档；8.组织过程资产结束项目或阶段的输出：1项目文件更新（经验教训登记册）;2.最终产品、服务或成果；3.项目最终报告；4.组织过程资产更新；（P269）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q159" class="quiz-anchor"></a></p><p><strong>159.</strong> 结束项目或阶段过程的输出，不包括（ ）。</p><ul><li>A．最终产品</li><li>B．验收的可交付成果</li><li>C．最终的服务或成果</li><li>D．项目最终报告</li></ul><details class="quiz" data-q="159" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：结束项目或阶段的输入：1.项目章程；2.项目管理计划；3.项目文件；4验收的可交付成果；5.立项管理文件；6.协议；7.采购文档；8.组织过程资产（P268-269）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q160" class="quiz-anchor"></a></p><p><strong>160.</strong> 小张作为项目经理负责项目 A，因需求方变动需要终止项目，接到通知后，小张采取的应对措施不合适的是（ ）。</p><ul><li>A．通知项目所有成员即刻停止工作</li><li>B．与所有合适的干系人整理项目历史信息和经验教训</li><li>C．制定程序，来调查和记录提前终止的原因</li><li>D．验收未全部完成的可交付成果</li></ul><details class="quiz" data-q="160" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：结束项目或阶段过程所需执行的活动包括：●为达到阶段或项目的完工或退出标准所必须的行动和活动；●为关闭项目合同协wo议或项niu目阶段合同协议所必须开展的活动；·为完成收集项目或阶段记录、审计项目成败、管理知识分享和传递、总结经验教训、存档项目信息以供组织未来使用等工作所必须开展的活动；·为向下一个阶段，或者向生产和(或》运营部门移交项目的产品、服务或成果所必须开展的行动和活动；·收集关于改进或更新…（P266）　<span class="quiz-src">2022 年上半年高项</span></p></details><p><a id="q161" class="quiz-anchor"></a></p><p><strong>161.</strong> 结束项目或阶段过程的主要作用包括（ ）。①存档项目或阶段信息②利用已有的组织知识，改进项目成果③对项目工作的可交付成果进行综合管理④确定项目工作的基础⑤释放组织团队资源</p><ul><li>A．①②⑤</li><li>B．①⑤</li><li>C．①③⑤</li><li>D．①④</li></ul><details class="quiz" data-q="161" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：结束项目或阶段的作用：①在档项目或阶段信息，完成计划的工作；②释放组织团队资源以展开新的工作（P265）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q162" class="quiz-anchor"></a></p><p><strong>162.</strong> 结束项目或阶段过程的输入是（ ）。</p><ul><li>A．批准的产品规范</li><li>B．最终产品、服务或成果</li><li>C．项目最终报告</li><li>D．经验教训知识库</li></ul><details class="quiz" data-q="162" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：验收的可交付成果可包括批准的产品规范、交货收据和工作绩效文件。对于分阶段实施的项目或提前取消的项目，还可能包括部分完成或中间的可交付成果（P267）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q163" class="quiz-anchor"></a></p><p><strong>163.</strong> 结束项目时，团队希望通过分析资源投入、团队沟通频率等变量与项目质量之间的关联性，以识别影响结果的主要因素。最适用于此场景的数据分析技术是（ ）。</p><ul><li>A．回归分析</li><li>B．文件分析</li><li>C．趋势分析</li><li>D．偏差分析</li></ul><details class="quiz" data-q="163" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：回归分析：该技术分析作用于项目结果的不同项目变量之间的相互关系，以提高未来项目的绩效（P268）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q164" class="quiz-anchor"></a></p><p><strong>164.</strong> 在“结束项目或阶段”过程需要参考的组织过程资产包括（ ），其内容包括经验教训、团队绩效评估和项目评价等。</p><ul><li>A．可行性研究报告</li><li>B．项目评估报告</li><li>C．项目或阶段收尾指南或要求</li><li>D．配置管理知识库</li></ul><details class="quiz" data-q="164" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：能够影响结束项目或阶段过程的组织过程资产主要包括：项目或阶段收尾指南或要求（如经验教训、项目终期审计、项目评价、产品确认、验收标准、合同收尾、资源重新分配、团队绩效评估以及知识传递）;配置管理知识库：包括组织标准、政策、程序和项目文件的各种版本及基准牛前宝扫码同 小辩通扫码的 公众 留中耳音 牛老师小红书（P268）　<span class="quiz-src">2026 年高项第 2 批</span></p></details></div>`,1)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};